            { achID = 12338, titleRU = "Обезоружен", titleEN = "Disarmed", descRU = "За 12 секунд уничтожьте сначала обе руки Кологарна, а потом убейте его самого в Ульдуаре.", descEN = "Destroy both of Kologarn's arms and then Kologarn himself within 12 seconds in Ulduar." },
            { achID = 12341, titleRU = "Безумная кошатница", titleEN = "Crazy Cat Lady", descRU = "Убейте Ауриайю в Ульдуаре, не уничтожая ее Часовых святилища.", descEN = "Defeat Auriaya in Ulduar without destroying her Sanctum Sentries." },
            { achID = 12347, titleRU = "Бесценный склад", titleEN = "I Could Say That This Cache Was Rare", descRU = "Победите Ходира в Ульдуаре, прежде чем он уничтожит свои зимние сокровища.", descEN = "Defeat Hodir in Ulduar before he shatters his Rare Cache of Winter." },
            { achID = 12352, titleRU = "Избавься от иллюзий", titleEN = "Lose Your Illusion", descRU = "Победите Торима в Ульдуаре в присутствии Сиф.", descEN = "Defeat Thorim in Ulduar while Sif is present." },
