            { achID = 4534, titleRU = "Косточка попалась (10 игроков)", titleEN = "Boned (10 player)", descRU = "Убейте лорда Ребрада в рейде на 10 игроков. Ни один участник рейда не должен быть проколот костяным шипом дольше 8 сек.", descEN = "Defeat Lord Marrowgar without any raid member remaining impaled for more than 8 seconds in 10-player mode." },
