            { achID = 4538, titleRU = "Танцы со слизнюками (10 игроков)", titleEN = "Dances with Oozes (10 player)", descRU = "Убейте Гниломорда в рейде на 10 игроков, не позволив большому слизнюку применить заклинание \"Взрыв нестабильного слизнюка\".", descEN = "Defeat Rotface without a Big Ooze casting Unstable Ooze Explosion in 10-player mode." },
            { achID = 4577, titleRU = "\"Масок нет!\" (10 игроков)", titleEN = "Flu Shot Shortage (10 player)", descRU = "Победите Тухлопуза в рейде на 10 игроков. Эффект \"Невосприимчивость к гнили\" не должен суммироваться ни на одном участнике рейда 3 раза.", descEN = "Defeat Festergut while none of the players in your raid group ever had 3 stacks of Inoculated in 10-player mode." },
            { achID = 4578, titleRU = "Тяжесть, вздутие и боль в животе... (10 игроков)", titleEN = "Nausea, Heartburn, Indigestion... (10 player)", descRU = "Убейте профессора Мерзоцида в рейде на 10 игроков, не используя способность поганища \"Рвотный слизнюк\".", descEN = "Defeat Professor Putricide without using Regurgitated Ooze on the Abomination in 10-player mode." },
            { achID = 4582, titleRU = "Разуплотнитель гелия (10 игроков)", titleEN = "The Orb Whisperer (10 player)", descRU = "Победите Кровавый Совет в рейде на 10 игроков. Ни один участник рейда не должен получить более 23000 ед. магического урона за один удар.", descEN = "Defeat the Blood Council without anyone in the raid taking more than 23,000 spell damage in a single hit in 10-player mode." },
            { achID = 4539, titleRU = "С вампирами жить – кровушку пить! (10 игроков)", titleEN = "Once Bitten, Twice Shy (10 player)", descRU = "Убейте Кровавую Королеву в рейде на 10 игроков, будучи вампиром, а затем еще раз, не становясь вампиром.", descEN = "Defeat Blood-Queen Lana'thel once as a vampire and again without becoming a vampire in 10-player mode." },
            { achID = 4579, titleRU = "Прогулки по порталам (10 игроков)", titleEN = "Portal Jockey (10 player)", descRU = "Зайдите в каждый портал, созданный Валитрией Сноходицей, до того, как полностью восстановите ей здоровье, в рейде на 10 игроков.", descEN = "Enter every portal spawned by Valithria Dreamwalker before healing her to full health in 10-player mode." },
            { achID = 4580, titleRU = "Таинственная дама (10 игроков)", titleEN = "All You Can Eat (10 player)", descRU = "Одолейте Синдрагосу в рейде на 10 игроков. Эффект \"Таинственная энергия\" не должен суммироваться ни на одном участнике рейда более 5 раз.", descEN = "Defeat Sindragosa in 10-player mode without any member of your raid receiving more than 5 stacks of Mystic Buffet." },
