            { achID = 5281, titleRU = "Хрусть – и пополам", titleEN = "Crushing Bones and Cracking Skulls", descRU = "Убейте Ром'огга Костекрушителя после того, как он воспользуется эффектом \"Крушитель черепов\", чтобы убить 10 разгневанных духов земли, в пещерах Черной горы в героическом режиме.", descEN = "Defeat Rom'ogg Bonecrusher after using his Skullcracker ability to kill 10 Angered Earth elementals in Blackrock Caverns on Heroic Difficulty." },
            { achID = 5282, titleRU = "Ошибка развития", titleEN = "Arrested Development", descRU = "Позвольте развиться трем ревнителям Корлы, убейте их и после этого победите Корлу в пещерах Черной горы в героическом режиме.", descEN = "Allow all three of Corla's zealots to evolve, then defeat Corla after slaying the evolved zealots in Blackrock Caverns on Heroic Difficulty." },
            { achID = 5283, titleRU = "Куй железо, пока горячо", titleEN = "Too Hot to Handle", descRU = "Убейте Карша Гнущего Сталь после того, как он 15 раз воспользуется эффектом перегретой обсидиановой брони в пещерах Черной горы в героическом режиме.", descEN = "Defeat Karsh Steelbender after he has reached 15 stacks of Superheated Quicksilver Armor in Blackrock Caverns on Heroic Difficulty." },
            { achID = 5284, titleRU = "Пелена перерожденного", titleEN = "Ascendant Descending", descRU = "Убейте повелителя перерожденных Обсидия в пещерах Черной горы в героическом режиме. Эффект \"Сумеречной пелены\" не должен суммироваться ни на одном участнике группы более 3 раз.", descEN = "Defeat Ascendant Lord Obsidius without any party member reaching 4 stacks of Crepuscular Veil in Blackrock Caverns on Heroic Difficulty." },
            { achID = 5287, titleRU = "Послушание наказуемо", titleEN = "Rotten to the Core", descRU = "Убейте 60 послушников за 10 секунд во время боя с верховной жрицей Азил в Каменных Недрах в героическом режиме.", descEN = "Defeat 60 Disciples within 10 seconds during the High Priestess Azil encounter in the Stonecore on Heroic Difficulty." },
            { achID = 5288, titleRU = "Не стоять на месте", titleEN = "No Static at All", descRU = "Не попадите под воздействие эффекта \"Хватка природы\" во время боя с Асаадом на Вершине Смерча в героическом режиме.", descEN = "Completely avoid the Static Cling effect during the Asaad encounter in the Vortex Pinnacle on Heroic Difficulty." },
            { achID = 5289, titleRU = "Полная пригоршня золота", titleEN = "Extra Credit Bonus Stage", descRU = "Соберите 5 золотых сфер в течение одного визита на Вершину Смерча в героическом режиме.", descEN = "Collect 5 Golden Orbs in a single visit to the Vortex Pinnacle on Heroic Difficulty." },
            { achID = 5290, titleRU = "Испепелить!", titleEN = "Kill It With Fire!", descRU = "Убейте 3 пылающие души во время боя с верховным пророком Баримом в Затерянном городе Тол'вире в героическом режиме.", descEN = "Defeat 3 Burning Souls during the High Prophet Barim encounter in Lost City of the Tol'vir on Heroic Difficulty." },
            { achID = 5291, titleRU = "Акрокалипсис сегодня", titleEN = "Acrocalypse Now", descRU = "Убейте 20 бесноватых кроколисков за 10 секунд во время битвы с Зубохлопом в Затерянном городе Тол'вире в героическом режиме.", descEN = "Defeat 20 Frenzied Crocolisks within 10 seconds during the Lockmaw encounter in the Lost City of the Tol'vir on Heroic Difficulty." },
            { achID = 5292, titleRU = "Гость с юга", titleEN = "Headed South", descRU = "Убейте Сиамата, повелителя южного ветра в Затерянном городе Тол'вире с 3 эффектами \"Разряда молнии\" в героическом режиме.", descEN = "Defeat Siamat, Lord of the South Wind, with 3 stacks of Lightning Charge in Lost City of the Tol'vir on Heroic Difficulty." },
            { achID = 5293, titleRU = "Ненавижу эту песню", titleEN = "I Hate That Song", descRU = "Убейте храмового стража Ануура, прервав его \"Раскатистый гимн\" за 15 или менее секунд в Чертогах Созидания в героическом режиме.", descEN = "Defeat Temple Guardian Anhuur without allowing him to sing Reverberating Hymn for more than 15 seconds in Halls of Origination on Heroic Difficulty." },
            { achID = 5294, titleRU = "Соломинка, ломающая спину верблюда", titleEN = "Straw That Broke the Camel's Back", descRU = "Убейте Пта Ярость Земли, сидя верхом на верблюде в Чертогах Созидания в героическом режиме.", descEN = "Defeat Earthrager Ptah while mounted on a camel in the Halls of Origination on Heroic Difficulty." },
            { achID = 5295, titleRU = "Солнцеворот", titleEN = "Sun of a....", descRU = "Убейте Раджа до того, как он успеет завершить полную стадию перезарядки в Чертогах Созидания в героическом режиме.", descEN = "Defeat Rajh before he completes an entire recharging phase in the Halls of Origination on Heroic Difficulty." },
            { achID = 5296, titleRU = "Быстрее света", titleEN = "Faster Than the Speed of Light", descRU = "Пройдите чертог Огней за 5 минут от момента входа в чертогах Созидания в героическом режиме.", descEN = "Complete the Vault of Lights within 5 minutes of entering in the Halls of Origination on Heroic Difficulty." },
            { achID = 5366, titleRU = "К рейду готов", titleEN = "Ready for Raiding", descRU = "Не попадите под воздействие \"Стены огня\" во время боя с Глубтоком в Мертвых копях в героическом режиме.", descEN = "Do not get hit by Fire Wall in the Glubtok encounter in Deadmines on Heroic Difficulty." },
            { achID = 5367, titleRU = "Крысиная стая", titleEN = "Rat Pack", descRU = "Убейте 20 рудниковых крыс во время боя с Хеликсом Отломчиксом в Мертвых копях в героическом режиме.", descEN = "Kill 20 Mine Rats during the Helix Gearbreaker encounter in Deadmines on Heroic Difficulty." },
            { achID = 5368, titleRU = "Удачливый прототип", titleEN = "Prototype Prodigy", descRU = "Добейтесь того, чтобы уровень здоровья опытной модели жнеца ни разу не опустился ниже 90%, пока Врагорез-5000 не будет побежден в Мертвых копях в героическом режиме.", descEN = "Keep the Prototype Reaper from falling below 90% health at any time before the Foe Reaper 5000 is defeated in Deadmines on Heroic Difficulty." },
            { achID = 5369, titleRU = "Ледяное спокойствие", titleEN = "It's Frost Damage", descRU = "Позвольте трем морозным парам использовать заклинание \"Сращение\" во время битвы с адмиралом Терзающим Ревом в Мертвых копях в героическом режиме.", descEN = "Allow three Freezing Vapors to cast Coalesce during the Admiral Ripsnarl encounter in Deadmines on Heroic Difficulty." },
            { achID = 5370, titleRU = "Я на диете!", titleEN = "I'm on a Diet", descRU = "Получите не более одного эффекта \"Тошнота\" во время боя с Пирожком в Мертвых копях в героическом режиме.", descEN = "Do not gain more than one stack of Nauseated during the Cookie encounter in Deadmines on Heroic Difficulty." },
            { achID = 5371, titleRU = "Великое воздаяние Ванессе ван Клиф", titleEN = "Vigorous VanCleef Vindicator", descRU = "Атакуйте Ванессу ван Клиф в Мертвых копях в героическом режиме в течение 5 минут после того, как вам впрыснут эликсир ночных кошмаров.", descEN = "Engage Vanessa VanCleef within 5 minutes of being inflicted with the Nightmare Elixir in Deadmines on Heroic Difficulty." },
            { achID = 5503, titleRU = "Извинения не принимаются", titleEN = "Pardon Denied", descRU = "Убейте барона Эшбери, не дав ему воспользоваться заклинанием \"Отложенная расправа\", в крепости Темного Клыка в героическом режиме.", descEN = "Defeat Baron Ashbury without letting him heal with Stay of Execution in Shadowfang Keep on Heroic Difficulty." },
            { achID = 5504, titleRU = "На землю!", titleEN = "To the Ground!", descRU = "Убейте командира Спрингвейла, не позволив ему попасть под действие эффекта \"Нечистое могущество\" в Крепости Темного Клыка в героическом режиме.", descEN = "Defeat Commander Springvale without allowing him to receive Unholy Empowerment in Shadowfang Keep on Heroic Difficulty." },
            { achID = 5505, titleRU = "Свинцовая закуска", titleEN = "Bullet Time", descRU = "Убейте 12 кровожадных вурдалаков при помощи заклинания \"Пистолетный обстрел\", а затем победите лорда Годфри в Крепости Темного Клыка в героическом режиме.", descEN = "Defeat 12 Bloodthirsty Ghouls with Pistol Barrage and then defeat Lord Godfrey in Shadowfang Keep on Heroic Difficulty." },
            { achID = 5298, titleRU = "Омлет без яиц", titleEN = "Don't Need to Break Eggs to Make an Omelet", descRU = "Убейте Эрудакса в Грим Батоле в героическом режиме, не позволив Безликому осквернителю наложить эффект сумеречной порчи ни на одно из яиц Алекстразы.", descEN = "Defeat Erudax without letting a Faceless Corruptor begin to cast Twilight Corruption on any of Alexstrasza's Eggs in Grim Batol on Heroic Difficulty." },
        },
    },
