            { achID = 5117, titleRU = "Валиона и Тералион (героич.)", titleEN = "Heroic: Valiona and Theralion", descRU = "Убейте Тералиона и Валиону в Сумеречном бастионе в героическом режиме.", descEN = "Defeat Valiona and Theralion in the Bastion of Twilight on Heroic Difficulty." },
