            { achID = 5306, titleRU = "Паразительный рейд", titleEN = "Parasite Evening", descRU = "Победите Магмаря в твердыне Крыла Тьмы. Никто из членов рейда не должен подвергнуться заражению паразитами.", descEN = "Defeat Magmaw in Blackwing Descent without anyone in the raid becoming infected with a parasite." },
            { achID = 5307, titleRU = "Ачив-о-трон", titleEN = "Achieve-a-tron", descRU = "Справьтесь с защитной системой \"Омнитрон\" в твердыне Крыла Тьмы, выполнив все перечисленные ниже условия.", descEN = "Defeat the Omnotron Defense System in Blackwing Descent while neutralizing the following attacks." },
            { achID = 5308, titleRU = "Молчание – золото", titleEN = "Silence is Golden", descRU = "Победите Атрамеда в твердыне Крыла Тьмы. Уровень шума ни у одного участника рейда не должен превышать 50%.", descEN = "Defeat Atramedes in Blackwing Descent without any raid member's sound bar going over 50%." },
