            { achID = 5310, titleRU = "Аберрантное поведение", titleEN = "Aberrant Behavior", descRU = "Убейте 12 аберраций за 10 секунд в бою с Малориаком в твердыне Крыла Тьмы, а затем убейте Малориака.", descEN = "Kill 12 Aberrations within 10 seconds on the Maloriak encounter in Blackwing Descent and then defeat Maloriak." },
            { achID = 4849, titleRU = "Дела семейные", titleEN = "Keeping it in the Family", descRU = "Добейтесь того, чтобы уровень здоровья Нефариана опустился ниже 50% до того, как он приземлится для решающей битвы, а затем убейте Нефариана в твердыне Крыла Тьмы.", descEN = "Damage Nefarian below 50% health before he lands for the final confrontation and then defeat Nefarian in Blackwing Descent." },
            { achID = 5300, titleRU = "Единственный выход", titleEN = "The Only Escape", descRU = "Убейте Халфия Змеереза после того, как убьете одного за другим двух драконов с интервалом не более 10 секунд. В данном случае стая маленьких изумрудных дракончиков считается за одного дракона.", descEN = "Defeat Halfus Wyrmbreaker after defeating two drakes within 10 seconds of each other. The Emerald Whelp pack counts as one drake for this purpose." },
            { achID = 4852, titleRU = "Двойной дракон", titleEN = "Double Dragon", descRU = "Убейте 6 сумеречных исчадий в сумеречном мире, а затем убейте Тералиона и Валиону в Сумеречном бастионе.", descEN = "Kill 6 Twilight Fiends in the Twilight Realm and then defeat Valiona and Theralion in the Bastion of Twilight." },
            { achID = 5311, titleRU = "Элементарно!", titleEN = "Elementary", descRU = "Убейте Элементиевое чудовище в Сумеречном бастионе, не позволив ему создать более одной области мерзлоты.", descEN = "Defeat the Elementium Monstrosity in the Bastion of Twilight while only allowing it to create a single Liquid Ice patch." },
            { achID = 5312, titleRU = "...бездна заглянет в тебя.", titleEN = "The Abyss Will Gaze Back Into You", descRU = "Убейте Чо'Галла в Сумеречном бастионе. Ни один участник рейда не должен получить больше 30% эффекта \"Порченая кровь\".", descEN = "Defeat Cho'gall in the Bastion of Twilight before any raid member earns more than 30% Corrupted Blood." },
            { achID = 5304, titleRU = "Прохладный прием", titleEN = "Stay Chill", descRU = "Убейте всех членов Конклава Ветра в троне Четырех Ветров. Все участники рейда должны находиться под воздействием эффекта \"Холодный ветер\", суммировавшегося как минимум 7 раз.", descEN = "Defeat the Conclave of Wind in the Throne of the Four Winds while everyone in the raid has at least 7 stacks of Wind Chill." },
