            { achID = 5806, titleRU = "Шэннокс (героич.)", titleEN = "Heroic: Shannox", descRU = "Убейте Шэннокса на Огненных Просторах в героическом режиме.", descEN = "Defeat Shannox in Firelands on Heroic Difficulty." },
            { achID = 5809, titleRU = "Алисразор (героич.)", titleEN = "Heroic: Alysrazor", descRU = "Убейте Алисразор на Огненных Просторах в героическом режиме.", descEN = "Defeat Alysrazor in Firelands on Heroic Difficulty." },
            { achID = 5805, titleRU = "Бейлрок (героич.)", titleEN = "Heroic: Baleroc", descRU = "Убейте Бейлрока на Огненных Просторах в героическом режиме.", descEN = "Defeat Baleroc in Firelands on Heroic Difficulty." },
            { achID = 5804, titleRU = "Мажордом Фэндрал Олений Шлем (героич.)", titleEN = "Heroic: Majordomo Fandral Staghelm", descRU = "Убейте мажордома Фэндрала Оленьего Шлема на Огненных Просторах в героическом режиме.", descEN = "Defeat Majordomo Fandral Staghelm in Firelands on Heroic Difficulty." },
            { achID = 5821, titleRU = "Пылающие небеса", titleEN = "Death from Above", descRU = "Во время битвы с Бет'тилак на Огненных Просторах убивайте пеплопрядов-трутней, когда они сидят на паутине.", descEN = "Only kill Cinderweb Drones while they are atop the web canopy during the Beth'tilac encounter in Firelands." },
            { achID = 5810, titleRU = "Направо пойдешь – налево пойдешь!", titleEN = "Not an Ambi-Turner", descRU = "Убейте повелителя Риолита на Огненных Просторах, не давая ему повернуть налево до тех пор, пока его броня цела.", descEN = "Defeat Lord Rhyolith in the Firelands without ever causing him to turn left while his armor is intact." },
            { achID = 5813, titleRU = "Сделай \"бочку\"!", titleEN = "Do a Barrel Roll!", descRU = "Убейте Алисразор на Огненных Просторах. При этом ни один из участников рейда не должен пострадать от перечисленных ниже атак:", descEN = "Defeat Alysrazor in the Firelands without any raid member getting hit by the following attacks." },
            { achID = 5829, titleRU = "Пока не сыграл в ящик", titleEN = "Bucket List", descRU = "За одно сражение с Шэнноксом успейте провести его через нижеперечисленные места, прежде чем убить:", descEN = "During a single engagement, bring Shannox to each of the following locations in the Firelands before dispatching him:" },
            { achID = 5830, titleRU = "Раздели боль", titleEN = "Share the Pain", descRU = "Убейте Бейлрока на Огненных Просторах. При этом никто из участников рейда не должен пострадать от эффекта \"Мучение\" более трех раз.", descEN = "Defeat Baleroc in the Firelands without allowing any member of your raid to suffer Torment more than three times." },
            { achID = 5799, titleRU = "Пройдет только кающийся...", titleEN = "Only the Penitent...", descRU = "Одновременно активируйте оба Пламени Фэндрала, но при этом ни один участник рейда не должен попасть под эффект \"Преклонись перед пламенем!\".", descEN = "Activate both of Fandral's Flames at once in Firelands without any raid member getting hit by Kneel to the Flame!" },
        },
    },
