        soloNoteEN = "100% soloable! 'Holding Hands' on Hagara can be completed solo using pets/totems or lightning conduit positioning.",
        subAchievements = {
            { achID = 6109, titleRU = "Морхок (героич.)", titleEN = "Heroic: Morchok", descRU = "Убейте Морхока в рейде \"Душа Дракона\" в героическом режиме.", descEN = "Defeat Morchok in Dragon Soul on Heroic Difficulty." },
            { achID = 6110, titleRU = "Полководец Зон'озз (героич.)", titleEN = "Heroic: Warlord Zon'ozz", descRU = "Убейте полководца Зон'озза в рейде \"Душа Дракона\" в героическом режиме.", descEN = "Defeat Warlord Zon'ozz in Dragon Soul on Heroic Difficulty." },
            { achID = 6111, titleRU = "Йор'садж Неспящий (героич.)", titleEN = "Heroic: Yor'sahj the Unsleeping", descRU = "Убейте Йор'саджа Неспящего в рейде \"Душа Дракона\" в героическом режиме.", descEN = "Defeat Yor'sahj the Unsleeping in Dragon Soul on Heroic Difficulty." },
            { achID = 6112, titleRU = "Хагара Владычица Штормов (героич.)", titleEN = "Heroic: Hagara the Stormbinder", descRU = "Убейте Хагару Владычицу Штормов в рейде \"Душа Дракона\" в героическом режиме.", descEN = "Defeat Hagara the Stormbinder in Dragon Soul on Heroic Difficulty." },
            { achID = 6113, titleRU = "Ультраксион (героич.)", titleEN = "Heroic: Ultraxion", descRU = "Убейте Ультраксиона в рейде \"Душа Дракона\" в героическом режиме.", descEN = "Defeat Ultraxion in Dragon Soul on Heroic Difficulty." },
            { achID = 6114, titleRU = "Воевода Черный Рог (героич.)", titleEN = "Heroic: Warmaster Blackhorn", descRU = "Убейте воеводу Черного Рога в рейде \"Душа Дракона\" в героическом режиме.", descEN = "Defeat Warmaster Blackhorn in Dragon Soul on Heroic Difficulty." },
            { achID = 6174, titleRU = "Не стой слишком близко", titleEN = "Don't Stand So Close to Me", descRU = "Одержите победу над Морхоком в рейде \"Душа Дракона\" в обычном или героическом режиме так, чтобы во время применения Морхоком заклинания \"Черная кровь земли\" в радиусе 5 метров от каждого персонажа не находилось никого в рейде на 10 игроков и не больше одного игрока в рейде на 25 игроков.", descEN = "Defeat Morchok in Dragon Soul on Normal or Heroic Difficulty without any two players (three players on 25-player mode) ever being within 5 yards of each other while Morchok is channeling Black Blood of the Earth." },
            { achID = 6129, titleRU = "Попробуй радугу на вкус!", titleEN = "Taste the Rainbow!", descRU = "Одержите победу над Йор'саджем Неспящим в обычном или героическом режиме, при этом испытав на себе следующие комбинации цветов.", descEN = "Experience the following color combinations, and then defeat Yor'sahj the Unsleeping on Normal or Heroic Difficulty." },
            { achID = 6128, titleRU = "Чемпион по пинг-понгу", titleEN = "Ping Pong Champion", descRU = "В обычном или героическом режиме дайте сфере рассоздания отразиться от игроков 10 раз, после чего одержите победу над полководцем Зон'оззом.", descEN = "Bounce the Void of the Unmaking 10 times off of players, and then defeat Warlord Zon'ozz on Normal or Heroic Difficulty." },
            { achID = 6084, titleRU = "Час до полночи", titleEN = "Minutes to Midnight", descRU = "Убейте Ультраксиона в рейде \"Душа Дракона\" в обычном или героическом режиме так, чтобы каждый участник рейда попал под удар Времени Сумерек не более одного раза.", descEN = "Defeat Ultraxion in Dragon Soul on Normal or Heroic Difficulty without any raid member being hit by Hour of Twilight more than once." },
            { achID = 6105, titleRU = "Защита палубы", titleEN = "Deck Defender", descRU = "Одержите верх над воеводой Черным Рогом в рейде \"Душа Дракона\" в обычном или героическом режиме так, чтобы \"Сумеречный обстрел\" не нанес \"Небесному огню\" повреждений.", descEN = "Defeat Warmaster Blackhorn on Normal or Heroic Difficulty without allowing any Twilight Barrages to damage the Skyfire." },
            { achID = 6133, titleRU = "Может, его укачает?..", titleEN = "Maybe He'll Get Dizzy...", descRU = "Успешно завершите бой \"Хребет Смертокрыла\" в обычном или героическом режиме, при этом заставив Смертокрыла наклониться налево, направо, снова налево и, наконец, снова направо.", descEN = "Defeat the Spine of Deathwing encounter on Normal or Heroic Difficulty after tricking Deathwing into performing the following roll sequence: Left, Right, Left, Right." },
            { achID = 6180, titleRU = "Радужный защитник", titleEN = "Chromatic Champion", descRU = "Уничтожьте Смертокрыла в рейде \"Душа Дракона\" в обычном или героическом режиме, начав бой с каждой из платформ Аспектов и позволив Смертокрылу атаковать этого Аспекта:", descEN = "Destroy Deathwing in Dragon Soul on Normal or Heroic Difficulty after beginning the encounter on each Aspect's platform and allowing Deathwing to assault that Aspect:" },
        },
