        mapID = 390, x = 80.0, y = 33.0,
        soloable = false,
        minPlayers = 2,
        soloNoteRU = "26 из 28 достижений делаются в соло, но «Уважение» (Поклониться 5 раз в Монастыре Шадо-Пан) и «Готов к рейду III» проще закрыть с напарником.",
        soloNoteEN = "Mostly soloable, though 1–2 criteria in Shado-Pan Monastery / Scholomance are much easier with a partner.",
        subAchievements = {
            { achID = 6925, titleRU = "Покоритель подземелий Пандарии", titleEN = "Pandaria Dungeon Hero", descRU = "Заработайте указанные ниже достижения в подземельях Mists of Pandaria в героическом режиме.", descEN = "Complete the heroic Pandaria dungeon achievements listed below." },
            { achID = 6460, titleRU = "Водобоязнь", titleEN = "Hydrophobia", descRU = "В храме Нефритовой Змеи победите Мудрого Мариса в героическом режиме, не получив урона от способностей \"Оскверненная вода\", \"Гидрокопье\" и \"Чудовищный поток\".", descEN = "Defeat Wise Mari without being hit by Corrupted Water, Hydrolance, or Wash Away in Temple of the Jade Serpent on Heroic Difficulty." },
            { achID = 6475, titleRU = "Очищение водой", titleEN = "Cleaning Up", descRU = "Победите Ша Сомнения в храме Нефритовой Змеи, пока не закончился эффект \"Чистая вода\".", descEN = "Defeat the Sha of Doubt in Temple of the Jade Serpent while under the effects of Purified Water." },
            { achID = 6671, titleRU = "Зерна сомнения", titleEN = "Seeds of Doubt", descRU = "Победите Ша Сомнения в храме Нефритовой Змеи в героическом режиме, находясь под воздействием эффекта четырех \"Зерен сомнения\".", descEN = "Defeat the Sha of Doubt in Temple of the Jade Serpent while under the effect of 4 Seeds of Doubt on Heroic difficulty." },
            { achID = 6420, titleRU = "Гнупокалипсис сегодня", titleEN = "Hopocalypse Now!", descRU = "Расплющите 100 гну-синей одним ударом молота в хмелеварне Буйных Портеров в героическом режиме.", descEN = "Smash 100 Virmen with a single hammer swing in Stormstout Brewery on Heroic Difficulty." },
            { achID = 6089, titleRU = "Катись отсюда!", titleEN = "Keep Rollin' Rollin' Rollin'", descRU = "Запустите в Ук-Ука 20 бочек с пойлом, а затем прикончите его в хмелеварне Буйных Портеров в героическом режиме.", descEN = "Kill Ook-Ook after assaulting him with 20 Rolling Brew Barrels in Stormstout Brewery on Heroic Difficulty." },
            { achID = 6400, titleRU = "И как он сюда забрался?", titleEN = "How Did He Get Up There?", descRU = "Избавьтесь от цепляющегося хозена в хмелеварне Буйных Портеров в любом режиме.", descEN = "Find a way to get the Hozen Clinger to let go in Stormstout Brewery on any difficulty." },
            { achID = 6402, titleRU = "Путешествие Лин-Тина среди трав", titleEN = "Ling-Ting's Herbal Journey", descRU = "Соберите всех 30 золотистых прыгунков, спрятанных в хмелеварне Буйных Портеров на любом уровне сложности.", descEN = "Collect all 30 Golden Hoplings hidden around the Stormstout Brewery on any difficulty." },
            { achID = 6478, titleRU = "Глинтрок-н-ролл", titleEN = "Glintrok N' Roll", descRU = "В течение пяти минут после того, как вас увидел глинтрок-разведчик, победите во дворце Могу'шан Геккана с его прихвостнями-глинтроками в героическом режиме.", descEN = "Defeat Gekkan and his Glintrok entourage in Mogu'shan Palace on Heroic difficulty within 5 minutes of being spotted by the Glintrok Scout." },
            { achID = 6736, titleRU = "А зачем эта кнопочка?", titleEN = "What Does This Button Do?", descRU = "Обратите тайный защитный механизм Синя Мастера Боя против него самого во дворце Могу'шан в героическом режиме.", descEN = "Use Xin the Weaponmaster's secret defense mechanism against him in Mogu'shan Palace on Heroic difficulty." },
            { achID = 6713, titleRU = "Цейхгауз цийлиней", titleEN = "Quarrelsome Quilen Quintet", descRU = "Соберите всех нефритовых цийлиней во дворце Могу'шан в героическом режиме.", descEN = "Collect all the Jade Quilen located throughout Mogu'Shan Palace on Heroic Difficulty." },
            { achID = 6477, titleRU = "Поклон", titleEN = "Respect", descRU = "Поклонитесь адептам Шадо-Пан в ответ на их поклон после поражения во время события с мастером Снежным Вихрем в монастыре Шадо-Пан в героическом режиме.", descEN = "Bow to the Shado-Pan Novices when they bow to you after being defeated during the Master Snowdrift event in Shado-Pan Monastery on Heroic Difficulty." },
            { achID = 6472, titleRU = "Очевидное решение", titleEN = "The Obvious Solution", descRU = "Уничтожьте оставшихся ша, находящихся в Закрытых покоях, а затем победите Ша Жестокости в монастыре Шадо-Пан в героическом режиме.", descEN = "Eliminate the remaining Sha imprisoned in the Sealed Chambers and then defeat the Sha of Violence in Shado-Pan Monastery on Heroic Difficulty." },
            { achID = 6471, titleRU = "Ненависть ведет к страданию", titleEN = "Hate Leads to Suffering", descRU = "Победите Тажаня Чжу в монастыре Шадо-Пан в героическом режиме так, чтобы ненависть каждого участника группы достигла максимального уровня.", descEN = "Defeat Taran Zhu while every party member is at maximum hatred in Shado-Pan Monastery on Heroic Difficulty." },
            { achID = 6479, titleRU = "Бомбермэн", titleEN = "Bomberman", descRU = "Во время битвы с диверсантом Кип'тилаком у врат Заходящего Солнца устройте 15 взрывов за 15 секунд в героическом режиме.", descEN = "Trigger 15 explosions within 15 seconds during the Saboteur Kip'tilak encounter in Gate of the Setting Sun on Heroic Difficulty." },
            { achID = 6476, titleRU = "Воинская повинность", titleEN = "Conscriptinator", descRU = "Суммируйте до 3-х раз эффект \"Осадок смолы\" в сражении с богомолами-новобранцами у врат Заходящего Солнца в героическом режиме.", descEN = "Gain three stacks of Resin Residue by defeating Mantid Conscripts in Gate of the Setting Sun on Heroic Difficulty." },
            { achID = 6684, titleRU = "Общество защиты животных", titleEN = "Humane Society", descRU = "Не убивая псов, победите псаря Брауна в залах Алого ордена в героическом режиме.", descEN = "Defeat Houndmaster Braun without killing any hounds in Scarlet Halls on Heroic Difficulty." },
            { achID = 6427, titleRU = "Мош-пит", titleEN = "Mosh Pit", descRU = "В залах Алого ордена сделайте так, чтобы 8 целей одновременно оказались в области действия клинков Света воителя Гарлана. Целями могут быть как игроки, так и защитники из Алого ордена. После этого одержите победу над Гарланом в героическом режиме.", descEN = "Get a combination of 8 players and Scarlet Defenders caught up in Armsmaster Harlan's Blades of Light simultaneously and then defeat Armsmaster Harlan in Scarlet Halls on Heroic Difficulty." },
            { achID = 6928, titleRU = "Горящий человек", titleEN = "Burning Man", descRU = "Сделайте так, чтобы брат Корлофф поджег шесть тренировочных манекенов, после чего одержите над ним победу в монастыре Алого ордена в героическом режиме.", descEN = "Cause Brother Korloff to light six nearby training dummies on fire, and then defeat him, in Scarlet Monastery on Heroic Difficulty." },
            { achID = 6929, titleRU = "И оставайтесь мертвыми!", titleEN = "And Stay Dead!", descRU = "Позвольте Верховному инквизитору Вайтмейн использовать \"Массовое воскрешение\", убейте всех воскрешенных заступников Алого ордена, после чего убейте Вайтмейн в героическом режиме в монастыре Алого ордена.", descEN = "Allow High Inquisitor Whitemane to cast Mass Resurrection, defeat all revived Scarlet Judicators, and then defeat Whitemane in Scarlet Monastery on Heroic Difficulty." },
            { achID = 6531, titleRU = "Внимание к деталям", titleEN = "Attention to Detail", descRU = "Победите Джандис Барову в Некроситете, не уничтожив ни одного ложного образа, в героическом режиме.", descEN = "Defeat Jandice Barov without ever eliminating a false image in Scholomance on Heroic Difficulty." },
            { achID = 6394, titleRU = "За мной не заржавеет", titleEN = "Rattle No More", descRU = "Победите Громоклина в Некроситете в героическом режиме, не позволив ему суммировать эффект \"Ржавчина\" более пяти раз.", descEN = "Defeat Rattlegore without allowing him to gain more than 5 stacks of Rusting in Scholomance on Heroic Difficulty." },
            { achID = 6396, titleRU = "Полнокровие", titleEN = "Sanguinarian", descRU = "Победите в Некроситете Рубщика Крастинова, суммировавшего 99 раз эффект \"Невыносимая жажда крови\", в героическом режиме.", descEN = "Defeat a Krastinovian Carver that has 99 stacks of Boiling Bloodthirst in Scholomance on Heroic Difficulty." },
            { achID = 6821, titleRU = "Последний звонок", titleEN = "School's Out Forever", descRU = "Уничтожьте в Некроситете 50 старых объектов исследований за 20 секунд в героическом режиме.", descEN = "Defeat 50 Expired Test Subjects within 20 seconds in Scholomance on Heroic Difficulty." },
            { achID = 6688, titleRU = "Где поддержка с воздуха?", titleEN = "Where's My Air Support?", descRU = "Во время осады храма Нюцзао прикончите сначала Сик'тика Желтокрыла, а потом командира Во'цзака в героическом режиме.", descEN = "Defeat Commander Vo'jak after having killed the Sik'thik Amberwing in Siege of Niuzao Temple on Heroic Difficulty." },
            { achID = 6485, titleRU = "Вернуть отправителю", titleEN = "Return to Sender", descRU = "Во время осады храма Нюцзао победите генерала Па'валака, 20 раз суммировавшего эффект взрыва, в героическом режиме.", descEN = "Defeat General Pa'valak while he has 20 stacks of Detonate in the Siege of Niuzao Temple on Heroic Difficulty." },
            { achID = 6822, titleRU = "Наперегонки с ветром", titleEN = "Run with the Wind", descRU = "Во время осады храма Нюцзао победите командующего флангом Нер'онока в героическом режиме, находясь под воздействием \"Решимости Тэньу\".", descEN = "Defeat Ner'onok in Siege of Niuzao Temple on Heroic Difficulty while under the effect of Tenwu's Resolve." },
            { achID = 6715, titleRU = "Наука о кислоте", titleEN = "Polyformic Acid Science", descRU = "Убейте боссов в Пандарии, находясь под действием выпитого пузырька полиметановой кислоты, в героическом режиме.", descEN = "Defeat bosses around Pandaria while under the effects of Polyformic Acid Potion on Heroic Difficulty." },
        },
