        soloNoteRU = "Большинство боссов закрывается в соло, но «Покажи мне свои приёмы!» (Воля Императора) и «Извини, ты это искал?» в Могу'шан требуют группу из 5 игроков!",
        soloNoteEN = "Most bosses are soloable, but 'Show Me Your Moves!' in Mogu'shan Vaults requires a group of 5 players!",
        subAchievements = {
            { achID = 6823, titleRU = "Любовь к собакам обязательна", titleEN = "Must Love Dogs", descRU = "Победите каменных стражей в Подземельях Могу'шан в обычном или героическом режиме так, чтобы каждого участника рейда сопровождал питомец-собака.", descEN = "Defeat the Stone Guard in Mogu'shan Vaults on Normal or Heroic difficulty while every member of your raid is accompanied by a canine companion pet." },
            { achID = 6674, titleRU = "Что бы ты ни сделал, я сделаю это лучше...", titleEN = "Anything You Can Do, I Can Do Better...", descRU = "Победите Фэна Проклятого в Подземельях Могу'шан в обычном или героическом режиме, повторив при этом каждую из приведенных ниже способностей.", descEN = "Defeat Feng the Accursed in Normal or Heroic difficulty after mimicking each of the following abilities:" },
            { achID = 7056, titleRU = "Вы не это ищете?", titleEN = "Sorry, Were You Looking for This?", descRU = "Активируйте древнюю реликвию могу во время битвы с Душеловом Гара'джалом в Подземельях Могу'шан в обычном или героическом режиме.", descEN = "Successfully activate the Ancient Mogu Artifact during the Gara'jal the Spiritbinder encounter in Mogu'shan Vaults on Normal or Heroic difficulty." },
            { achID = 6686, titleRU = "Шестицилиндровый", titleEN = "Straight Six", descRU = "Успейте отключить 6 неземных средоточий одно за другим, потратив на это не более чем 10 сек., а потом победите Элегона в Подземельях Могу'шан в обычном или героическом режиме.", descEN = "Deactivate six Empyreal Focuses within 10 seconds of each other, and then defeat Elegon in Mogu'shan Vaults on Normal or Heroic difficulty." },
            { achID = 6937, titleRU = "Вот паразит!", titleEN = "Overzealous", descRU = "Победите в Сердце Страха императорского визиря Зор'лока, пока все участники рейда находятся под воздействием эффекта \"Ненасытный паразит\".", descEN = "Defeat Imperial Vizier Zor'lok while every member of the raid is afflicted with the Zealous Parasite debuff." },
            { achID = 6936, titleRU = "Свеча на ветру", titleEN = "Candle in the Wind", descRU = "Пока не погасли четыре жаровни, победите повелителя клинков Та'яка в Сердце Страха в обычном или героическом режиме.", descEN = "Defeat Blade Lord Ta'yak while all four braziers are lit in Heart of Fear on Normal or Heroic difficulty." },
            { achID = 6553, titleRU = "Только не по ногам!", titleEN = "Like an Arrow to the Face", descRU = "Победите Гаралона в Сердце Страха в обычном или героическом режиме, не уничтожая его ног.", descEN = "Defeat Garalon in Heart of Fear on Normal or Heroic difficulty without destroying any of his legs." },
            { achID = 6683, titleRU = "Не больше двух", titleEN = "Less Than Three", descRU = "Победите в Сердце Страха повелителя ветров Мел'джарака в обычном или героическом режиме, контролируя не больше двух его приспешников.", descEN = "Defeat Wind Lord Mel'jarak without crowd-controlling more than 2 of his swarm at once on Normal or Heroic difficulty in Heart of Fear." },
            { achID = 6518, titleRU = "Говорят, тебе нравится янтарь…", titleEN = "I Heard You Like Amber...", descRU = "Уничтожайте живой янтарь в горящем янтаре до тех пор, пока не образуются 8 соприкасающихся луж, после чего победите ваятеля янтаря Ун'сока в Сердце Страха в обычном или героическом режиме.", descEN = "Kill Living Amber in Burning Amber until at least 8 pools overlap, and then defeat Amber-Shaper Un'sok on Normal or Heroic difficulty in Heart of Fear." },
            { achID = 6922, titleRU = "Не теряя времени", titleEN = "Timing is Everything", descRU = "Убейте двух кор'тиков-разорителей одного за другим с интервалом не более 10 сек., а затем победите великую императрицу Шек'зир в Сердце Страха в обычном или героическом режиме.", descEN = "Defeat two Kor'thik Reavers within 10 seconds of each other, and then defeat Grand Empress Shek'zeer in Heart of Fear on Normal or Heroic difficulty." },
            { achID = 6717, titleRU = "Переполняющая мощь", titleEN = "Power Overwhelming", descRU = "Победите Вечных защитников на террасе Вечной Весны в обычном или героическом режиме, каждый раз убивая разного защитника последним.", descEN = "Defeat the Protectors of the Endless with each protector as the last member alive on Normal or Heroic difficulty in Terrace of Endless Spring." },
            { achID = 6824, titleRU = "Объятия мандибул", titleEN = "Face Clutchers", descRU = "Победите Лэй Ши на террасе Вечной Весны в обычном или героическом режиме, пока на всех членов рейда действует \"Паразитический захват\".", descEN = "Defeat Lei Shi while all members of the raid are afflicted by Parasitic Clutch in Terrace of Endless Spring on Normal or Heroic difficulty." },
            { achID = 6933, titleRU = "У меня цветы не вянут!", titleEN = "Who's Got Two Green Thumbs?", descRU = "Одержите победу в битве с Цулоном, не дав погибнуть заколдованному растению.", descEN = "Win the Tsulong encounter while keeping the Enchanted Plant alive." },
            { achID = 6825, titleRU = "Убийца разума", titleEN = "The Mind-Killer", descRU = "Победите Ша Страха на террасе Вечной Весны в нормальном или героическом режиме так, чтобы ни один из участников рейда не оказался под действием эффекта дрожи от \"Залпа ужаса\" или \"Дыхания страха\".", descEN = "Defeat the Sha of Fear in Terrace of Endless Spring on Normal or Heroic difficulty without any raid members being feared by Dread Spray or Breath of Fear." },
            { achID = 6719, titleRU = "Каменные стражи (героич.)", titleEN = "Heroic: Stone Guard", descRU = "Победите каменных стражей в Подземельях Могу'шан в героическом режиме.", descEN = "Defeat the Stone Guard in Mogu'shan Vaults on Heroic difficulty." },
