        soloNoteRU = "100% закрывается в соло! В патче 10.1.5 башни Галакраса и «Давай длинный пас» (Норусхен / Ша Гордыни) адаптированы под соло-игроков!",
        soloNoteEN = "100% soloable! Since patch 10.1.5, Galakras and 'Go Long' have been updated to be fully soloable.",
        subAchievements = {
            { achID = 8536, titleRU = "Довольно слез", titleEN = "No More Tears", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме победите Глубиния после уничтожения 10 слез Дола.", descEN = "Defeat Immerseus after killing 10 Tears of the Vale in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8528, titleRU = "Эстафета", titleEN = "Go Long", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме за время одной фазы \"Крайних мер\" передайте знак страданий по меньшей мере 5 разным игрокам, общее расстояние между которыми составляет 200 м или больше, а затем победите павших защитников.", descEN = "Transfer the Mark of Anguish to at least 5 unique players over a total of 200 yards or more during a single Desperate Measures phase, and then defeat the Fallen Protectors in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8532, titleRU = "Никто не пройдет", titleEN = "None Shall Pass", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме победите слияние порчи, не позволив ни одному фрагменту высвобожденной порчи слиться с ним.", descEN = "Defeat the Amalgam of Corruption without allowing any unleashed corruption to fuse with it in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8521, titleRU = "Усмири свою гордыню", titleEN = "Swallow Your Pride", descRU = "Победите Ша Гордыни в ходе осады Оргриммара в обычном или более сложном режиме, но ни один игрок не должен получить эффект \"Гордыня\" от проявлений гордыни, пока Норусхен жив.", descEN = "Defeat the Sha of Pride in Siege of Orgrimmar on Normal difficulty or higher after no player has gained Pride from Manifestations of Pride while Norushen is alive." },
            { achID = 8530, titleRU = "Бессмертные защитники", titleEN = "The Immortal Vanguard", descRU = "Победите Галакраса в ходе осады Оргриммара в обычном или более сложном режиме, не допустив гибели ни одного дружественного персонажа.", descEN = "Defeat Galakras without having allowed a single friendly NPC to perish in battle in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8520, titleRU = "Мин нет!", titleEN = "Fire in the Hole!", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме раздавите 6 перегревшихся ползучих мин, а затем победите \"Железного исполина\".", descEN = "Stomp on 6 superheated Crawler Mines and then defeat the Iron Juggernaut in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8453, titleRU = "Спасательная операция", titleEN = "Rescue Raiders", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме спасите заключенных в клетки узников, группу невольных участников сражения и Цзи Огненную Лапу, прежде чем одолеть кор'кронских темных шаманов.", descEN = "Rescue a set of caged prisoners, a group of unwilling combat participants, and Ji Firepaw before defeating the Kor'kron Dark Shaman in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8448, titleRU = "Гамон нас спасет!", titleEN = "Gamon Will Save Us!", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме победите генерала Назгрима, пока Гамон жив и участвует в бою.", descEN = "Defeat General Nazgrim while Gamon is alive and participating in the battle in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8538, titleRU = "Неограниченный потенциал", titleEN = "Unlimited Potential", descRU = "Превратите оскверненного головоруба в слившуюся порчу и затем одержите победу над Малкороком в ходе осады Оргриммара в обычном или более сложном режиме.", descEN = "Transform a Corrupted Skullsplitter into a Corrupted Amalgamation and then defeat Malkorok in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8529, titleRU = "Перекрестный огонь", titleEN = "Criss Cross", descRU = "Пройдите событие \"Пандарийские трофеи\" в ходе осады Оргриммара в обычном или более сложном режиме так, чтобы ни один участник рейда не убил сразу и богомола, и могу.", descEN = "Complete the Spoils of Pandaria encounter in Siege of Orgrimmar on Normal difficulty or higher without any raid member defeating both a Mantid and a Mogu enemy." },
            { achID = 8527, titleRU = "Мегаулитка против гигантского динозавра", titleEN = "Giant Dinosaur vs. Mega Snail", descRU = "Откройте клеть с тремя замками во время боя с Током Кровожадным в ходе осады Оргриммара в обычном или более сложном режиме. После победы над Током позвольте выпущенному существу попировать на трупе поверженного врага.", descEN = "Open the Thrice-Locked Cage during the Thok the Bloodthirsty encounter in Siege of Orgrimmar on Normal difficulty or higher, and then allow its inhabitant to feast upon Thok's corpse once you have defeated the encounter." },
            { achID = 8543, titleRU = "Лазеры, магниты, буры! Ой-ой!", titleEN = "Lasers and Magnets and Drills! Oh My!", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме победите мастера осады Черноплавса, не уничтожая перечисленные ниже виды оружия.", descEN = "Defeat Siegecrafter Blackfuse without destroying each of the following weapons in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8531, titleRU = "Я идеален!", titleEN = "Now We are the Paragon", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме получите силы трех различных Идеалов, а затем победите остальных Идеалов.", descEN = "Defeat the Paragons after assuming the mantle of three different Paragons in Siege of Orgrimmar on Normal difficulty or higher." },
            { achID = 8537, titleRU = "Страйк!", titleEN = "Strike!", descRU = "В ходе осады Оргриммара в обычном или более сложном режиме убейте 18 кор'кронских вестников войны одной железной звездой, а затем победите Гарроша.", descEN = "Kill 18 Kor'kron Warbringers with a single Iron Star and then defeat Garrosh in Siege of Orgrimmar on Normal difficulty or higher." },
        },
    },
    {
        mountID = 623,
