        titleRU = "Слава герою Дренора",
        titleEN = "Glory of the Draenor Hero",
        expansionRU = "Warlords of Draenor",
        expansionEN = "Warlords of Draenor",
        instanceRU = "Героические подземелья Дренора",
        instanceEN = "Draenor Heroic Dungeons",
        zoneRU = "Ашран / Дренор",
        zoneEN = "Ashran / Draenor",
        mapID = 539, x = 45.0, y = 50.0,
        soloable = true,
        minPlayers = 1,
        soloNoteRU = "100% закрывается в соло на максимальном уровне!",
        soloNoteEN = "100% soloable at max level!",
        subAchievements = {
            { achID = 9391, titleRU = "Покоритель подземелий Дренора", titleEN = "Draenor Dungeon Hero", descRU = "Заработайте указанные ниже достижения в подземельях Дренора в героическом режиме.", descEN = "Complete the Draenor Heroic dungeon achievements listed below." },
            { achID = 8993, titleRU = "Дар земли и огня", titleEN = "A Gift of Earth and Fire", descRU = "Победите Магмолата в шлаковых шахтах Кровавого Молота в героическом режиме, пока Катастрофа и Уничтожитель еще живы.", descEN = "Defeat Magmolatus while Calamity and Ruination are still alive in Bloodmaul Slag Mines on Heroic difficulty." },
            { achID = 9005, titleRU = "Идем со мной, если хочешь жить", titleEN = "Come With Me If You Want to Live", descRU = "В Шлаковых шахтах Кровавого Молота победите Гуг'рокка в героическом режиме после того, как отыщется меч Кромана-варвара.", descEN = "Defeat Gug'rokk alongside Croman the Barbarian after finding his sword in Bloodmaul Slag Mines on Heroic difficulty." },
            { achID = 9008, titleRU = "Дренор горит?", titleEN = "Is Draenor on Fire?", descRU = "Победите Гуг'рокка в героическом режиме в шлаковых шахтах Кровавого Молота, не уничтожая нестабильных шлаковых элементалей.", descEN = "Defeat Gug'rokk without killing any Unstable Slag in Bloodmaul Slag Mines on Heroic difficulty." },
            { achID = 9083, titleRU = "Милитарист, экспансионист", titleEN = "Militaristic, Expansionist", descRU = "Убейте в Железных доках в героическом режиме раздирателя плоти Нок'Гара, пока осадный мастер Олугар, страж ям Гварнок и защитница Друна живы и остаются в бою.", descEN = "Defeat Fleshrender Nok'gar in Iron Docks on Heroic difficulty, while Siegemaster Olugar, Pitwarden Gwarnok, and Champion Druna remain alive and in the fight." },
            { achID = 9081, titleRU = "Очень вовремя", titleEN = "Expert Timing", descRU = "Убейте в Железных доках в героическом режиме 4 огронов-работников, не участвующих в бою, используя одну железную звезду.", descEN = "Slay 4 Ogron Laborers that are not in combat using a single Iron Star in Iron Docks on Heroic Difficulty." },
            { achID = 9082, titleRU = "В укрытие!", titleEN = "Take Cover!", descRU = "Победите Черепона в Железных доках в героическом режиме так, чтобы ни один игрок не попал под \"Обстрел\" или \"Обратную тягу\".", descEN = "Defeat Skulloc in Iron Docks on Heroic difficulty without any players getting hit by Cannon Barrage or Backdraft." },
            { achID = 9023, titleRU = "...Все они падут", titleEN = "...They All Fall Down", descRU = "Победите стражницу душ Ниами в героическом режиме, одолев 12 павших аукенайских защитников в Аукиндоне с интервалом не более 3 секунд.", descEN = "Defeat Soulbinder Nyami after defeating 12 fallen Auchenai protectors within 3 seconds in Auchindoun on Heroic difficulty." },
            { achID = 9024, titleRU = "Вот почему у нас никогда не будет клевых штук", titleEN = "This Is Why We Can't Have Nice Things", descRU = "Победите рельсмейстера Искролета и Борку Бесчеловечного в героическом режиме, уничтожив все сундуки с драгоценным имуществом Полли в депо Мрачных Путей.", descEN = "Defeat Railmaster Rocketspark and Borka the Brute after destroying all of the Priceless Paraphernalia in Grimrail Depot on Heroic difficulty." },
            { achID = 9007, titleRU = "Без билета", titleEN = "No Ticket", descRU = "Победите Нитрогга Громовую Гору в героическом режиме, выбив с поля боя не менее 20 противников в депо Мрачных Путей.", descEN = "Defeat Nitrogg Thundertower after abruptly removing 20 enemies from the Grimrail in Grimrail Depot on Heroic difficulty." },
            { achID = 9017, titleRU = "Никто не водится со мной", titleEN = "Water Management", descRU = "Победите в героическом режиме Сухокожего в Вечном Цветении, не дав ему восполнить запас энергии воды.", descEN = "Defeat Witherbark without allowing him to replenish any of his Aqueous Energy in The Everbloom on Heroic difficulty." },
            { achID = 9223, titleRU = "Газонокосилка", titleEN = "Weed Whacker", descRU = "Победите Йалну в Вечном Цветении в героическом режиме так, чтобы не погиб ни один боевой маг Кирин-Тора.", descEN = "Defeat Yalnu without any Kirin Tor Battle-Mages dying in The Everbloom on Heroic difficulty." },
            { achID = 9018, titleRU = "Кто ты по зодиаку?", titleEN = "What's Your Sign?", descRU = "Победите Садану Кровавое Безумие в героическом режиме так, чтобы при этом на Некрополе Призрачной Луны горели лишь руны, совпадающие с ее активным лунным циклом.", descEN = "Defeat Sadana Bloodfury while only having the runes that correspond to her active lunar cycle lit in Shadowmoon Burial Grounds on Heroic difficulty." },
            { achID = 9025, titleRU = "Жуткая жижа", titleEN = "Icky Ichors", descRU = "Победите Костебрюха в героическом режиме, скормив ему перед этим 25 трупных паучат в Некрополе Призрачной Луны.", descEN = "Defeat Bonemaw after having fed him 25 Corpse Skitterlings in Shadowmoon Burial Grounds on Heroic difficulty." },
            { achID = 9026, titleRU = "Души пропавших", titleEN = "Souls of the Lost", descRU = "Победите Нер'зула в героическом режиме, убив перед этим 2 избранных им скелетов Костяного ритуала в течение 5 секунд в Некрополе Призрачной Луны.", descEN = "Defeat Ner'zhul after slaying 2 Ritual of Bones skeletons within 5 seconds of each other in Shadowmoon Burial Grounds on Heroic difficulty." },
            { achID = 9045, titleRU = "Как работают магниты?", titleEN = "Magnets, How Do They Work?", descRU = "Победите владыку руды Гор'ашана в верхней части пика Черной горы в героическом режиме, не дав ему 4 раза применить способность \"Какофония грома\".", descEN = "Defeat Orebender Gor'ashan without allowing him to cast Thundering Cacophony 4 times in Upper Blackrock Spire on Heroic difficulty." },
            { achID = 9058, titleRU = "Ли-и-и-и-и-и-и-и-ирой?..", titleEN = "Leeeeeeeeeeeeeroy...?", descRU = "Помогите Лирою Дженкинсу найти наплечники Благочестия в верхней части пика Черной горы в героическом режиме.", descEN = "Assist Leeroy Jenkins in recovering his Devout shoulders in Upper Blackrock Spire on Heroic difficulty." },
            { achID = 9056, titleRU = "Огонь, огонь, огонь, агония!", titleEN = "Bridge Over Troubled Fire", descRU = "Убейте 20 дракончиков Ярокрыла за 10 секунд в верхней части пика Черной горы в героическом режиме, сражаясь с Ярокрылом Неукротимым.", descEN = "Kill 20 Ragewing Whelps in 10 seconds while fighting Ragewing the Untamed in Upper Blackrock Spire on Heroic difficulty." },
            { achID = 9057, titleRU = "Драконья Пасть? Тут вам и пропасть!", titleEN = "Dragonmaw? More Like Dragonfall!", descRU = "Убейте 5 пепельных железных драконов, прежде чем убить полководца Зелу в верхней части пика Черной горы в героическом режиме.", descEN = "Kill 5 Emberscale Ironflight before defeating Warlord Zaela in Upper Blackrock Spire on Heroic difficulty." },
        },
    },
