        mapID = 543, x = 51.5, y = 27.2,
        soloable = false,
        minPlayers = 2,
        soloNoteRU = "16 из 17 достижений делаются в соло, но «Лови, но не роняй!» (Ганс'гар и Франзок в Литейной) требует 2 игроков для переброски руды!",
        soloNoteEN = "16 of 17 achievements are soloable, but 'Ya, We've Got Time...' (Hans'gar & Franzok) requires 2 players to pass the ore!",
        subAchievements = {
            { achID = 8948, titleRU = "Поджигай!", titleEN = "Flame On!", descRU = "В нападении на клан Верховного Молота в обычном или более сложном режиме победите Каргата Острорука, не разрушив ни одного огненного столба.", descEN = "Defeat Kargath Bladefist in Highmaul without destroying any Fire Pillars on Normal difficulty or higher." },
            { achID = 8947, titleRU = "Шевелись, червяк!", titleEN = "Hurry Up, Maggot!", descRU = "В нападении на клан Верховного Молота в обычном или более сложном режиме заставьте Мясника убить 6 личинок, перед тем как вы победите его.", descEN = "Cause the Butcher in Highmaul to slay 6 Maggots before defeating him on Normal difficulty or higher." },
            { achID = 8974, titleRU = "Полный крах", titleEN = "More Like Wrecked-us", descRU = "Победите Тектоника в землях Верховного Молота, уничтожив все его восемь частиц с интервалом не более 10 секунд в обычном или более сложном режиме.", descEN = "Defeat Tectus in Highmaul by destroying all eight Motes of Tectus within 10 seconds of each other on Normal difficulty or higher." },
            { achID = 8975, titleRU = "Жюльен на скорую руку", titleEN = "A Fungus Among Us", descRU = "Накопите 15 эффектов \"Огня в венах\", а затем победите Бурогриба в нападении на клан Верховного Молота в обычном или более сложном режиме.", descEN = "Gain 15 stacks of Burning Infusion and then defeat Brackenspore in Highmaul on Normal difficulty or higher." },
            { achID = 8958, titleRU = "Братья по оружию", titleEN = "Brothers in Arms", descRU = "В нападении на клан Верховного Молота в обычном или более сложном режиме победите огронов-близнецов так, чтобы расстояние между ними не успело увеличиться больше чем на 30%.", descEN = "Defeat the Twin Ogron in Highmaul without their Disposition ever exceeding 30% on Normal difficulty or higher." },
            { achID = 8976, titleRU = "Парная аннигиляция", titleEN = "Pair Annihilation", descRU = "В ходе нападения на клан Верховного Молота в обычном или более сложном режиме победите Ко'рага так, чтобы менее 15 сфер избыточной энергии коснулось земли или игроков без нейтрализующего щита.", descEN = "Defeat Ko'ragh in Highmaul with fewer than 15 Overflowing Energy orbs touching the ground or players without Nullification Barrier, on Normal difficulty or higher." },
            { achID = 8977, titleRU = "Передача власти", titleEN = "Lineage of Power", descRU = "Добейтесь, чтобы горианский боевой маг получил эффекты рун укрепления и воспроизведения, а затем одолейте его, после чего победите императора Мар'гока в нападении на клан Верховного Молота в обычном или более сложном режиме.", descEN = "Empower and defeat a Fortified Replicating Gorian Warmage and then defeat Imperator Mar'gok in Highmaul on Normal difficulty or higher." },
            { achID = 8978, titleRU = "Железная цена", titleEN = "The Iron Price", descRU = "Соберите 3 куска беспримесной истинной железной руды, а затем победите Груула в литейной клана Черной горы в обычном или более сложном режиме.", descEN = "Collect 3 Pristine True Iron Ores and then defeat Gruul in Blackrock Foundry in Normal difficulty or higher." },
            { achID = 8979, titleRU = "Добра нажевать", titleEN = "He Shoots, He Ores", descRU = "Бросьте нестабильную руду в дробилку, а затем победите Рудожуя в литейной клана Черной горы в обычном или более сложном режиме.", descEN = "Deposit the Volatile Ore in the Ore Grinder, and then defeat Oregorger in Blackrock Foundry on Normal difficulty or higher." },
            { achID = 8980, titleRU = "Никакого прессинга", titleEN = "Stamp Stamp Revolution", descRU = "В обычном или более сложном режиме победите Ганс'гара и Франзока в литейной клана Черной горы так, чтобы ни один из участников рейда не угодил под пресс.", descEN = "Defeat Hans'gar and Franzok in Blackrock Foundry without any raid member being crushed by a stamping press on Normal difficulty or higher." },
            { achID = 8981, titleRU = "Смерть на скаку", titleEN = "Fain Would Lie Down", descRU = "Победите Дармака Повелителя Зверей в литейной клана Черной горы в обычном или более сложном режиме, предварительно заставив его оседлать каждого из перечисленных ниже зверей первым:", descEN = "Defeat Beastlord Darmac in Blackrock Foundry on Normal difficulty or higher after causing him to mount each beast first:" },
            { achID = 8929, titleRU = "Стальные нервы, стальной нос", titleEN = "The Steel Has Been Brought", descRU = "Создайте гарнизон и победите Ка'граз Пламенную в литейной клана Черной горы в обычном или более сложном режиме, не убивая Акнора Сталеноса.", descEN = "Defeat Flamebender Ka'graz in Blackrock Foundry without killing Aknor Steelbringer on Normal difficulty or higher after securing your garrison." },
            { achID = 8982, titleRU = "Всегда найдется поезд побольше", titleEN = "There's Always a Bigger Train", descRU = "В литейной клана Черной горы в обычном или более сложном режиме устройте торжествующему заводному крушителю поездов ироничную гибель.", descEN = "Engineer the ironic demise of an Exulting Wind-Up Train Wrecker in Blackrock Foundry on Normal difficulty or higher." },
            { achID = 8930, titleRU = "Времени еще полно...", titleEN = "Ya, We've Got Time...", descRU = "Пройдите событие \"Горнило\" в литейной клана Черной горы в обычном или более сложном режиме, победив всех четырех повелительниц изначальных стихий с интервалом не более 10 сек.", descEN = "Complete the Blast Furnace encounter in Blackrock Foundry after defeating all four Primal Elementalists within 10 seconds of each other, on Normal difficulty or higher." },
            { achID = 8983, titleRU = "Дай руку, друг!", titleEN = "Would You Give Me a Hand?", descRU = "Победите 10 рук из удерживающей земли за 5 секунд, а затем победите Кромога в литейной клана Черной горы в обычном или более сложном режиме.", descEN = "Defeat 10 Grasping Earth hands within 5 seconds and then defeat Kromog in Blackrock Foundry on Normal difficulty or higher." },
            { achID = 8984, titleRU = "Промедление смерти подобно", titleEN = "Be Quick or Be Dead", descRU = "Победите Железных леди с интервалом в 10 секунд в литейной клана Черной горы в обычном или более сложном режиме.", descEN = "Defeat the Iron Maidens within 10 seconds of each other in Blackrock Foundry on Normal difficulty or higher." },
            { achID = 8952, titleRU = "Пепел, пепел...", titleEN = "Ashes, Ashes...", descRU = "В литейной клана Черной горы победите Чернорука в обычном или более сложном режиме после того, как поймаете 20 кусочков падающего пепла.", descEN = "Defeat Blackhand in Blackrock Foundry after catching 20 Falling Ashes on Normal difficulty or higher." },
