            { achID = 10013, titleRU = "Волна за волной", titleEN = "Waves Came Crashing Down All Around", descRU = "Победите Кормрока в цитадели Адского Пламени в обычном или более сложном режиме, не получив при этом урона ни от одной из волн.", descEN = "Defeat Kormrok in Hellfire Citadel without taking damage from any of the waves on Normal difficulty or higher." },
            { achID = 10054, titleRU = "Не бойся Жнеца", titleEN = "Don't Fear the Reaper", descRU = "Убейте всех трех членов верховного совета Адского Пламени в цитадели Адского Пламени с интервалом не более 10 секунд в обычном или более сложном режиме.", descEN = "Defeat all 3 members of the Hellfire High Council in Hellfire Citadel within 10 seconds of each other on Normal difficulty or higher." },
            { achID = 9972, titleRU = "Наперегонки со слизью", titleEN = "A Race Against Slime", descRU = "Победите Килрогга Мертвого Глаза в цитадели Адского Пламени в обычном или более сложном режиме так, чтобы Ариок выжил в бою.", descEN = "Defeat Kilrogg Deadeye in Hellfire Citadel with Ariok surviving the encounter on Normal difficulty or higher." },
            { achID = 9979, titleRU = "Кровожадный аппетит", titleEN = "Get In My Belly!", descRU = "Победите Кровожада в цитадели Адского Пламени в обычном или более сложном режиме, вначале уничтожив Душу ведьмы.", descEN = "Defeat Gorefiend after killing the Soul of the Crone in Hellfire Citadel on Normal difficulty or higher." },
            { achID = 9988, titleRU = "Стремительное око", titleEN = "Pro Toss", descRU = "Победите повелителя теней Искара в цитадели Адского Пламени в обычном или более сложном режиме так, чтобы при этом Глаз Анзу не находился у одного и того же игрока более 5 секунд подряд.", descEN = "Defeat Shadow-Lord Iskar in Hellfire Citadel without anyone holding the Eye of Anzu for more than 5 seconds in a row, on Normal difficulty or higher." },
            { achID = 10086, titleRU = "Задушевность", titleEN = "I'm a Soul Man", descRU = "Победите Сокретара Вечного в цитадели Адского Пламени после убийства 20 навязчивых духов с интервалом не более 10 секунд в обычном или более сложном режиме.", descEN = "Defeat Socrethar the Eternal in Hellfire Citadel after killing 20 Haunting Souls within 10 seconds on Normal difficulty or higher." },
            { achID = 10012, titleRU = "Земля была цветущей и плодородной...", titleEN = "This Land Was Green and Good Until...", descRU = "Победите повелителя Скверны Закууна в цитадели Адского Пламени в обычном или более сложном режиме, не поглотив ни одного громыхающего разлома.", descEN = "Defeat Fel Lord Zakuun in Hellfire Citadel without absorbing any Rumbling Fissures on Normal difficulty or higher." },
            { achID = 10087, titleRU = "Держите их подальше друг от друга", titleEN = "You Gotta Keep 'em Separated", descRU = "Победите Ксул'горака в цитадели Адского Пламени, не допустив ни одного срабатывания \"Аннигиляции Тьмы и Скверны\" в обычном или более сложном режиме.", descEN = "Defeat Xhul'horac in Hellfire Citadel without triggering any Shadowfel Annihilations on Normal difficulty or higher." },
            { achID = 9989, titleRU = "Мягкий каратель", titleEN = "Non-Lethal Enforcer", descRU = "Победите Деспотичную Велари в цитадели Адского Пламени в обычном или более сложном режиме, не убив древнего карателя.", descEN = "Defeat Tyrant Velhari in Hellfire Citadel without killing the Ancient Enforcer on Normal difficulty or higher." },
            { achID = 10030, titleRU = "Плохие Манер(от)ы", titleEN = "Bad Manner(oth)", descRU = "Уничтожьте владыку судеб при помощи \"Усиленного искателя Скверны\", а затем победите Маннорота в цитадели Адского Пламени в обычном или более сложном режиме.", descEN = "Kill a Doom Lord using Empowered Felseeker, then defeat Mannoroth in Hellfire Citadel on Normal difficulty or higher." },
            { achID = 10073, titleRU = "Отзвуки Рокового Огня", titleEN = "Echoes of Doomfire", descRU = "Победите Архимонда в цитадели Адского Пламени в обычном или более сложном режиме так, чтобы \"Роковой Огонь\" еще действовал.", descEN = "Defeat Archimonde in Hellfire Citadel with Doomfire still active on Normal difficulty or higher." },
