            { achID = 10457, titleRU = "Пена морская", titleEN = "Stay Salty", descRU = "Одолейте леди Кольцо Ненависти в Оке Азшары после того, как уничтожите не менее 11 капель морской воды с помощью одного \"Проклятия ведьмы\", в эпохальном режиме.", descEN = "Defeat Lady Hatecoil after destroying 11 or more Saltsea Globules with a single Curse of the Witch in Eye of Azshara on Mythic difficulty." },
            { achID = 10458, titleRU = "К рейду готов V", titleEN = "Ready for Raiding V", descRU = "Одолейте Гнев Азшары, не попав под действие \"Магического резонанса\" или \"Резонанса от магии льда\" в Оке Азшары в эпохальном режиме.", descEN = "Defeat the Wrath of Azshara without being struck by Magic or Frost Resonance in Eye of Azshara on Mythic difficulty." },
            { achID = 10766, titleRU = "А как же яйца?", titleEN = "Egg-cellent!", descRU = "Победите Дресарона в чаще Темного Сердца, предварительно уничтожив порожденное ненавистью поганище, в эпохальном режиме.", descEN = "Defeat Dresaron after slaying the Hatespawn Abomination in Darkheart Thicket on Mythic difficulty." },
            { achID = 10769, titleRU = "Дотла!", titleEN = "Burning Down the House", descRU = "Сразите Тень Ксавия в чаще Темного Сердца, когда у него есть 10 зарядов \"Апокалиптического усиления\", в эпохальном режиме.", descEN = "Defeat the Shade of Xavius while he has 10 stacks of Apocalyptic Empowerment in Darkheart Thicket on Mythic difficulty." },
            { achID = 10996, titleRU = "Улиточный атлас", titleEN = "Got to Ketchum All", descRU = "С помощью Кетчумской таблички соберите отпечатки всех улиток с именами в логове Нелтариона.", descEN = "Use the Ketchum Tablet to acquire imprints of all the named snails within Neltharion's Lair." },
            { achID = 10875, titleRU = "Хищный аппетит", titleEN = "Can't Eat Just One", descRU = "Победите Нараксас в логове Нелтариона, после того как она накопит 6 зарядов эффекта \"Хищность\", в эпохальном режиме.", descEN = "Defeat Naraxas after she gains 6 stacks of Ravenous in Neltharion's Lair on Mythic difficulty." },
            { achID = 10544, titleRU = "Что-то меня штормит", titleEN = "Stag Party", descRU = "Победите штормового дракона, предварительно дав ему накопить 10 зарядов эффекта \"Смертельный удар,\" в Чертогах Доблести в эпохальном режиме.", descEN = "Defeat a Storm Drake after allowing it to gain 10 stacks of Killing Blow in Halls of Valor on Mythic difficulty." },
            { achID = 10542, titleRU = "Мед – это очень странный предмет", titleEN = "I Got What You Mead", descRU = "Облейте всех четырех королей врайкулов из кружки меда в Чертогах Доблести в эпохальном режиме.", descEN = "Splash all four vrykul kings with a Mug of Mead in Halls of Valor on Mythic difficulty." },
            { achID = 10543, titleRU = "Предохранитель", titleEN = "Surge Protector", descRU = "Победите Одина, не дав никому из закаленных бурей уничтожителей успешно применить \"Импульс\", в эпохальном режиме.", descEN = "Defeat Odyn without any Stormforged Obliterators successfully casting Surge in Halls of Valor on Mythic difficulty." },
            { achID = 10554, titleRU = "Я слепил пирожок!", titleEN = "I Made a Food!", descRU = "Во время штурма Аметистовой крепости убейте Тухломорда после того, как уничтожите черную желчь, в эпохальном режиме.", descEN = "Defeat Festerface after slaying a Black Bile in Assault on Violet Hold on Mythic difficulty." },
            { achID = 10553, titleRU = "Вы все делаете только ХУЖЕ!", titleEN = "You're Just Making It WORSE!", descRU = "Во время штурма Аметистовой крепости в эпохальном режиме одолейте Миллифисент Манашторм, когда она начнет сильно злиться на вас.", descEN = "Defeat Millificent Manastorm after she becomes very cross with you in Assault on Violet Hold on Mythic difficulty." },
            { achID = 10680, titleRU = "Кто боится темноты?", titleEN = "Who's Afraid of the Dark?", descRU = "Победите Кордану в Казематах Стражей в эпохальном режиме, успешно уклоняясь от ползучей гибели и не используя свет Элуны, пока босс находится в воздухе.", descEN = "Defeat Cordana after successfully navigating Creeping Doom without holding Elune's Light while she is in the air, in Vault of the Wardens on Mythic difficulty." },
            { achID = 10707, titleRU = "Призрак освещенный", titleEN = "A Specter, Illuminated", descRU = "Осветите и освободите призрака отмщения в Казематах Стражей в эпохальном режиме.", descEN = "Illuminate and free the Specter of Vengeance in Vault of the Wardens on Mythic difficulty." },
            { achID = 10709, titleRU = "Скверные воспоминания", titleEN = "You Used to Scrawl Me In Your Fel Tome", descRU = "Найдите все записи из дневника Иллисанны Гребень Ворона в крепости Черной Ладьи.", descEN = "Find all entries of Illysanna Ravencrest's diary in Black Rook Hold." },
            { achID = 10710, titleRU = "Стенания Черной Ладьи", titleEN = "Black Rook Moan", descRU = "Победите Слияние душ в крепости Черной Ладьи, предварительно уничтожив беспокойного духа, в эпохальном режиме.", descEN = "Defeat Amalgam of Souls after killing a Frustrated Soul in Black Rook Hold on Mythic difficulty." },
            { achID = 10711, titleRU = "Бесполезные помощники", titleEN = "Adds? More Like Bads", descRU = "Победите Иллисанну Гребень Ворона в крепости Черной Ладьи, не убив ни одного из ее союзников, в эпохальном режиме.", descEN = "Defeat Illysanna Ravencrest without killing any of her allies in Black Rook Hold on Mythic difficulty." },
            { achID = 10413, titleRU = "Мгновенная карма", titleEN = "Instant Karma", descRU = "Победите Имирона в Утробе Душ, перед этим поразив \"Дерзким ударом\" 6 восставших воинов, в эпохальном режиме.", descEN = "Defeat Ymiron after defiantly striking down 6 Risen Warriors in Maw of Souls on Mythic difficulty." },
            { achID = 10411, titleRU = "Хельхейм не знает ярости", titleEN = "Helheim Hath No Fury", descRU = "Спасите пленную валь'киру в Утробе Душ в эпохальном режиме.", descEN = "Rescue the Captured Val'kyr in Maw of Souls on Mythic difficulty." },
            { achID = 10412, titleRU = "Бедные несчастные души", titleEN = "Poor Unfortunate Souls", descRU = "Победите Хелию в Утробе Душ, пока все участники группы являются бедными несчастными душами, в эпохальном режиме.", descEN = "Defeat Helya in Maw of Souls while all group members are Poor Unfortunate Souls on Mythic difficulty." },
            { achID = 10776, titleRU = "Времени в обрез", titleEN = "No Time to Waste", descRU = "Победите советника Вандроса в катакомбах Сурамара, не убив ни одного вневременного призрака, в эпохальном режиме.", descEN = "Defeat Advisor Vandros without killing any Timeless Wraiths in the Arcway on Mythic difficulty." },
            { achID = 10775, titleRU = "Мокрый пол", titleEN = "Clean House", descRU = "Победите Корстилакса в катакомбах Сурамара, не дав пропасть ни одной луже энергии Ночного Колодца, в эпохальном режиме.", descEN = "Defeat Corstilax without any pools of Nightwell Energy expiring in the Arcway on Mythic difficulty." },
            { achID = 10773, titleRU = "Неточные чары", titleEN = "Arcanic Cling", descRU = "Победите Иванира в катакомбах Сурамара, не получив урона от \"Энергетического заряда\", в эпохальном режиме.", descEN = "Defeat Ivanyr without taking any damage from Charged Bolt in The Arcway on Mythic difficulty." },
            { achID = 10610, titleRU = "В ожидании Гердо", titleEN = "Waiting for Gerdo", descRU = "Выведите из строя все посты, после того как капитан патруля Гердо подаст им сигнал, а потом победите его самого в Квартале Звезд в эпохальном режиме.", descEN = "Disable each of the watchposts after Patrol Captain Gerdo signals them and then defeat him in Court of Stars on Mythic difficulty." },
            { achID = 10611, titleRU = "Следим за словами", titleEN = "Dropping Some Eaves", descRU = "Подслушайте разговор между советником Меландром и Великим магистром Элисандой в Квартале Звезд в эпохальном режиме.", descEN = "Witness the conversation between Advisor Melandrus and Grand Magistrix Elisande in Court of Stars on Mythic difficulty." },
