            { achID = 10771, titleRU = "Больше никакой паутины", titleEN = "Webbing Crashers", descRU = "Победите Элерет Дикую Лань в Изумрудном Кошмаре, уничтожив все пульсирующие яйца, в обычном или более сложном режиме.", descEN = "Defeat Elerethe Renferal in The Emerald Nightmare after destroying all her Pulsing Egg Sacs during the encounter on Normal difficulty or higher." },
            { achID = 10753, titleRU = "Защита медведей", titleEN = "Scare Bear", descRU = "Победите Урсока в Изумрудном Кошмаре, защищая Тура Яролапа от гибели, в обычном или более сложном режиме.", descEN = "Defeat Ursoc in The Emerald Nightmare while keeping Tur Ragepaw alive on Normal difficulty or higher." },
            { achID = 10830, titleRU = "Точно в красный глаз", titleEN = "Took the Red Eye Down", descRU = "Победите Ил'гинота в Изумрудном Кошмаре, перед этим 20 раз нанеся урон глазу Ил'гинота с помощью \"Кошмарного взрыва\" за 10 секунд, в обычном или более сложном режиме.", descEN = "Defeat Il'gynoth in The Emerald Nightmare after inflicting 20 Nightmare Explosions on the Eye of Il'gynoth within 10 seconds on Normal difficulty or higher." },
            { achID = 10663, titleRU = "Турне по воображаемым драконам", titleEN = "Imagined Dragons World Tour", descRU = "Сразите Исондру в Изумрудном Кошмаре, когда у всех участников рейда есть сущности Сна от всех четырех врат, в обычном или более сложном режиме.", descEN = "Defeat Ysondre in The Emerald Nightmare while all members of the raid have Dream Essences from all four gateway locations on Normal difficulty or higher." },
            { achID = 10772, titleRU = "Да пребудет с тобой сила(-ы)!", titleEN = "Use the Force(s)", descRU = "Победите Кенария в Изумрудном Кошмаре, не очищая перечисленные силы Кошмара, в обычном или более сложном режиме.", descEN = "Defeat Cenarius without cleansing each of the following Forces of Nightmare in The Emerald Nightmare on Normal difficulty or higher." },
            { achID = 10755, titleRU = "Рассеять тень", titleEN = "I Attack the Darkness", descRU = "Победите обитателя теней в каждой фазе боя с Ксавием в Изумрудном Кошмаре в обычном или более сложном режиме.", descEN = "Defeat a Creature in the Dark during each of phase of the encounter with Xavius in The Emerald Nightmare on Normal difficulty or higher." },
            { achID = 10678, titleRU = "Реванш в клетке", titleEN = "Cage Rematch", descRU = "Победите Скорпирона в Цитадели Ночи в обычном или более сложном режиме. За бой ни один игрок не должен выходить за пределы кругов в центре.", descEN = "Defeat Skorpyron in The Nighthold on Normal difficulty or higher without any player leaving the center rings." },
            { achID = 10697, titleRU = "Световое представление", titleEN = "Grand Opening", descRU = "Активируйте все светильники вокруг Ночного Колодца, а затем победите хрономатическую аномалию в Цитадели Ночи в обычном или более сложном режиме.", descEN = "Activate all the spotlights around the Nightwell and then defeat the Chronomatic Anomaly in The Nighthold, on Normal difficulty or higher." },
            { achID = 10742, titleRU = "Без глютена", titleEN = "Gluten Free", descRU = "Победите Триллиакса в Цитадели Ночи, съев не более 20 токсичных объедков, в обычном или более сложном режиме.", descEN = "Defeat Trilliax in The Nighthold while eating no more than 20 Toxic Slices on Normal Difficulty or higher." },
            { achID = 10817, titleRU = "Смена декораций", titleEN = "A Change In Scenery", descRU = "Сразитесь с заклинательницей клинков Алуриэль и одержите над ней победу в указанных местах Цитадели Ночи в обычном или более сложном режиме. Заклинательница должна попасть в место назначения в течение 120 секунд после начала боя и оставаться там до его окончания:", descEN = "Engage and defeat Spellblade Aluriel in the following areas of The Nighthold on Normal difficulty or higher. She must reach her destination within 120 seconds of entering combat and remain there until defeated:" },
            { achID = 10851, titleRU = "Элементально!", titleEN = "Elementalry!", descRU = "Победите звездного авгура Этрея в Цитадели Ночи, предварительно уничтожив путешествующего элементаля Пустоты, в обычном или более сложном режиме.", descEN = "Defeat Star Augur Etraeus in The Nighthold after having defeated a Well-Traveled Nether Elemental on Normal difficulty or higher." },
            { achID = 10704, titleRU = "Тебе не по зубам", titleEN = "Not For You", descRU = "Победите Тихондрия в Цитадели Ночи, не получив урона от Эха Бездны, в обычном или более сложном режиме.", descEN = "Defeat Tichondrius in The Nighthold without taking any damage from Echoes of the Void on Normal difficulty or higher." },
            { achID = 10575, titleRU = "Горящие мосты", titleEN = "Burning Bridges", descRU = "Победите Кроса в Цитадели Ночи, предварительно затушив 15 раскаленных углей, в обычном или более сложном режиме.", descEN = "Defeat Krosus in The Nighthold after quenching 15 Burning Embers on Normal difficulty or higher." },
            { achID = 10699, titleRU = "Предательская бесконечность", titleEN = "Infinitesimal", descRU = "Дайте себя предать дракончику бесконечности, после чего убейте его во время боя с Великим магистром Элисандой, а затем победите Великого магистра Элисанду в Цитадели Ночи в героическом или более сложном режиме.", descEN = "Get betrayed by and then defeat an Infinite Whelpling during the Grand Magistrix Elisande encounter, then defeat Grand Magistrix Elisande in The Nighthold, on Normal difficulty or higher." },
            { achID = 10696, titleRU = "Смежить очи", titleEN = "I've Got My Eyes On You", descRU = "Победите Гул'дана в Цитадели Ночи, предварительно уничтожив 16 очей Гул'дана в течение 3 секунд, в обычном или более сложном режиме.", descEN = "Defeat Gul'dan in The Nighthold on Normal difficulty or higher, after defeating 16 Eyes of Gul'dan within 3 seconds." },
        },
    },
