        mapID = 885, x = 54.8, y = 62.4,
        soloable = false,
        minPlayers = 3,
        soloNoteRU = "9 из 11 достижений делаются в соло, но «Портальный бой» (Хазабель) и «Звёздная пыль» (Аграммар / Ковен) требуют группу 3–5 человек.",
        soloNoteEN = "9 of 11 achievements are soloable, but 'Portal Combat' (Hasabel) requires 3–5 players.",
        subAchievements = {
            { achID = 11949, titleRU = "Страшный противник", titleEN = "Hard to Kill", descRU = "Победите ловца душ Имонара в Анторусе, Пылающем Троне в обычном или более сложном режиме, после того как сработают все ловушки на мосту.", descEN = "Defeat Imonar the Soulhunter in Antorus, the Burning Throne after triggering every trap on the bridge on Normal difficulty or higher." },
            { achID = 11948, titleRU = "Вместе мы сильнее", titleEN = "Together We Stand", descRU = "Победите Вариматраса в Анторусе, Пылающем Троне в обычном или более сложном режиме, не дав ему использовать способность \"Один в темноте\".", descEN = "Defeat Varimathras in Antorus, the Burning Throne on Normal difficulty or higher without triggering Alone in the Darkness." },
            { achID = 11930, titleRU = "Охотник на червей", titleEN = "Worm-monger", descRU = "Победите разрушителя миров Кин'гарота в Анторусе, Пылающем Троне, после того как уничтожите 16 гнилошкурых червей в обычном или более сложном режиме.", descEN = "Defeat Garothi Worldbreaker in Antorus, the Burning Throne after decimating 16 Blightscale Worms on Normal difficulty or higher." },
            { achID = 11928, titleRU = "Война порталов", titleEN = "Portal Combat", descRU = "Победите хранительницу порталов Азабель в Анторусе, Пылающем Троне в обычном или более сложном режиме, после того как она откроет хаотический разлом.", descEN = "Defeat Portal Keeper Hasabel in Antorus, the Burning Throne after opening a chaotic rift on Normal difficulty or higher." },
            { achID = 11915, titleRU = "Не злись понапрасну", titleEN = "Don't Sweat the Technique", descRU = "Победите Агграмара, перед этим победив проявление Тайшалака в Анторусе, Пылающем Троне, в обычном или более сложном режиме.", descEN = "Defeat Aggramar after slaying a Manifestation of Taeshalach in Antorus, the Burning Throne on Normal difficulty or higher." },
            { achID = 12065, titleRU = "Милые песики", titleEN = "Hounds Good To Me", descRU = "Победите гончих Скверны Саргераса в Анторусе, Пылающем Троне в обычном или более сложном режиме при условии, что обе гончие находились под действием 5 эффектов \"Насыщение Скверной\".", descEN = "Defeat the Felhounds of Sargeras in Antorus, the Burning Throne on Normal difficulty or higher with both Felhounds afflicted with 5 stacks of Fel Imbuement." },
            { achID = 12129, titleRU = "Это Зал Войны!", titleEN = "This is the War Room!", descRU = "Победите военный совет Анторуса в Анторусе, Пылающем Троне, установив не более трех генераторов щита Скверны.", descEN = "Defeat the Antoran High Command in Antorus, the Burning Throne while placing three or fewer Felshield Emitters." },
            { achID = 12067, titleRU = "Сферы влияния", titleEN = "Spheres of Influence", descRU = "Соберите 5 сфер жизни, размещенных вокруг святилища Эонар в Анторусе, Пылающем Троне в обычном или более сложном режиме.", descEN = "Collect the 5 Orbs of Life placed around Eonar's sanctuary in Antorus, the Burning Throne on Normal difficulty or higher." },
            { achID = 12030, titleRU = "Мир крутится вокруг меня", titleEN = "The World Revolves Around Me", descRU = "Победите Кин'гарота в Анторусе, Пылающем Троне при 9 активных демонических бомбах в обычном или более сложном режиме.", descEN = "Defeat Kin'garoth with 9 Diabolic Bombs active in Antorus, the Burning Throne on Normal difficulty or higher." },
            { achID = 12046, titleRU = "Помни о титанах", titleEN = "Remember the Titans", descRU = "Победите ковен шиварр в Анторусе, Пылающем Троне в обычном или более сложном режиме при условии, что как минимум одно из мучений уцелело.", descEN = "Defeat the Coven of Shivarra in Antorus, the Burning Throne on Normal difficulty or higher while at least one of each Torment survives." },
            { achID = 12257, titleRU = "Рыцари звездной пыли", titleEN = "Stardust Crusaders", descRU = "Соберите 20 частиц титанической мощи в течение 5 сек. и победите Аргуса Порабощенного в Анторусе, Пылающем Троне в обычном или более сложном режиме.", descEN = "Collect 20 Motes of Titanic Power within 5 seconds and then defeat Argus the Unmaker in Antorus, the Burning Throne on Normal difficulty or higher." },
        },
    },
