        instanceEN = "BfA Mythic Dungeons",
        zoneRU = "Боралус / Дазар'алор",
        zoneEN = "Boralus / Dazar'alor",
        mapID = 1161, x = 70.0, y = 35.0,
        soloable = true,
        minPlayers = 1,
        soloNoteRU = "100% закрывается в соло! В патче 10.1.5 все групповые механики подземелий BfA переделаны под сольное прохождение.",
        soloNoteEN = "100% soloable! Patch 10.1.5 updated all BfA Mythic dungeon achievements to be fully soloable.",
        subAchievements = {
            { achID = 12550, titleRU = "Кто с Живцом придет...", titleEN = "Pecking Order", descRU = "Преподнесите Живцу его любимое угощение в Вольной Гавани в эпохальном режиме.", descEN = "Serve Sharkbait his favorite meal in Freehold on Mythic difficulty." },
            { achID = 12548, titleRU = "Полный впер-р-ред!", titleEN = "I'm in Charge Now!", descRU = "Победите небесного капитана Крагга, перед этим призвав и победив Глазастика, в Вольной Гавани в эпохальном режиме.", descEN = "Defeat Skycap'n Kragg after summoning and defeating Patches in Freehold on Mythic difficulty." },
            { achID = 12998, titleRU = "Богатства Красавчика", titleEN = "That Sweete Booty", descRU = "Победите Красавчика Харлана после уничтожения трех сундуков с сокровищами в Вольной Гавани в эпохальном режиме.", descEN = "Defeat Harlan Sweete after destroying three Chests o' Booty in Freehold on Mythic Difficulty." },
            { achID = 12489, titleRU = "Потеря профессии", titleEN = "Losing My Profession", descRU = "Найдите и победите перечисленных ниже противников в усадьбе Уэйкрестов и во время осады Боралуса в эпохальном режиме.", descEN = "Find and kill all of the enemies in Waycrest Manor and Siege of Boralus listed below on Mythic difficulty." },
            { achID = 12495, titleRU = "Бегите так, будто на вас горит одежда", titleEN = "Run Wild Like a Man On Fire", descRU = "Победите оживленного голиафа в усадьбе Уэйкрестов до того, как он накопит 12 эффектов \"Жатвы душ\", в эпохальном режиме.", descEN = "Defeat the Soulbound Goliath without it gaining 12 stacks of Soul Harvest in Waycrest Manor on Mythic difficulty." },
            { achID = 12490, titleRU = "Алхимики шутят", titleEN = "Alchemical Romance", descRU = "Уничтожьте три трупа меченных смертью поработителей одним зарядом алхимического огня, а затем победите горака Тула в усадьбе Уэйкрестов в эпохальном режиме.", descEN = "Destroy three Deathtouched Slavers's corpses using a single Alchemical Fire, then defeat Gorak Tul in Waycrest Manor on Mythic difficulty." },
            { achID = 12600, titleRU = "Дыхание святилища", titleEN = "Breath of the Shrine", descRU = "Используя дыхание святилища, зажгите церемониальные огни в храме Святилища Штормов в эпохальном режиме.", descEN = "Light the ceremonial fires within the temple using the Shrine's Breath in Shrine of the Storm on Mythic difficulty." },
            { achID = 12601, titleRU = "Бездна дремлет", titleEN = "The Void Lies Sleeping", descRU = "Победите лорда Штормсонга в Святилище Штормов в эпохальном режиме, не прикасаясь к пробудившейся Бездне.", descEN = "Defeat Lord Stormsong without coming into contact with any Awoken Void in Shrine of the Storm on Mythic difficulty." },
            { achID = 12602, titleRU = "Не доверяй никому", titleEN = "Trust No One", descRU = "Победите Вол'зит Шепчущую в Святилище Штормов в эпохальном режиме после того, как все участники группы будут поражены сводящими с ума снами.", descEN = "Defeat Vol'zith the Whisperer while all party members are afflicted with Maddening Dreams in Shrine of the Storm on Mythic difficulty." },
            { achID = 12270, titleRU = "Не так страшен сглаз", titleEN = "Bringing Hexy Back", descRU = "Победите всех четырех боссов в Атал'Дазаре на эпохальном уровне сложности, пока хотя бы один участник группы находится под воздействием эффекта \"Заразный сглаз\".", descEN = "Defeat all four bosses with at least one party member under the affects of Unstable Hex in Atal'Dazar on Mythic difficulty." },
            { achID = 12272, titleRU = "Золотая лихорадка", titleEN = "Gold Fever", descRU = "Победите жрицу Алун'зу в Атал'Дазаре на эпохальном уровне сложности после убийства смертоносной порчи.", descEN = "Defeat Priestess Alun'za after defeating the Fatal Corruption in Atal'Dazar on Mythic difficulty." },
            { achID = 12273, titleRU = "Зажжено!", titleEN = "It's Lit!", descRU = "Победите Язму в Атал'Дазаре на эпохальном уровне сложности, пока горят все четыре жаровни пламени Тьмы.", descEN = "Defeat Yazma while all four Shadowflame Sconces are lit in Atal'Dazar on Mythic difficulty." },
            { achID = 12549, titleRU = "Сердитый парень", titleEN = "Not a Fun Guy", descRU = "Победите Мусашитаки, а затем заклинателя спор Занчу в Подгнилье в эпохальном режиме.", descEN = "Defeat Musashitake, then defeat Sporecaller Zancha in Underrot on Mythic difficulty." },
            { achID = 12498, titleRU = "Сейчас не до порчи", titleEN = "Taint Nobody Got Time For That", descRU = "Победите старейшину Ликсу так, чтобы при этом ни одного участника группы не поразила порча Г'ууна в Подгнилье в эпохальном режиме.", descEN = "Defeat Elder Leaxa without any party member receiving the Taint of G'huun in Underrot on Mythic difficulty." },
            { achID = 12499, titleRU = "Спорное выживание", titleEN = "Sporely Alive", descRU = "Победите освобожденное чудовище в Подгнилье в эпохальном режиме так, чтобы при этом не погибла ни одна разлагающая спора.", descEN = "Defeat the Unbound Abomination without any Rotting Spores dying in Underrot on Mythic difficulty." },
            { achID = 12457, titleRU = "Ни одного бочонка не пострадало", titleEN = "Remix to Ignition", descRU = "Победите рыцаря-капитана Валири в Тол Дагоре на эпохальном уровне сложности, не допустив ни одного взрыва бочонка с взрывчаткой.", descEN = "Defeat Knight Captain Valyri without detonating any Munitions in Tol Dagor on Mythic difficulty." },
            { achID = 12462, titleRU = "Наша остановочка", titleEN = "Shot Through the Heart", descRU = "Победите надзирателя Корги в Тол Дагоре на эпохальном уровне сложности, после того как все участники группы будут одновременно оглушены останавливающим сердце ядом.", descEN = "Defeat Overseer Korgus after all party members have been stunned by Heartstopper Venom at the same time in Tol Dagor on Mythic difficulty." },
            { achID = 12855, titleRU = "Вторжение на поле", titleEN = "Pitch Invasion", descRU = "Победите Ледли, а затем платный разгонятель толпы в \"ЗОЛОТОЙ ЖИЛЕ!!!\" в эпохальном режиме.", descEN = "Defeat the Coin-Operated Crowd Pummeler after defeating Ledley the Bold in The MOTHERLODE!! on Mythic difficulty." },
            { achID = 12854, titleRU = "К рейду готов VI", titleEN = "Ready for Raiding VI", descRU = "Победите шефа Разданка, не получив урон от пулемета, микроракет, большой красной ракеты и избежав прямого попадания \"Мощного удара буром\" в \"ЗОЛОТОЙ ЖИЛЕ!!!\" в эпохальном режиме.", descEN = "Defeat Mogul Razdunk without being struck by Gatling Gun, Micro Missiles, Big Red Rocket, or a direct hit from Drill Smash in The MOTHERLODE!! on Mythic difficulty." },
            { achID = 12727, titleRU = "Стой рядом", titleEN = "Stand by Me", descRU = "Победите жуткого капитана Локвуд в подземелье \"Осада Боралуса\" в эпохальном режиме, не допустив, чтобы она отступила с помощью \"Изворотливости\".", descEN = "Never let Dread Captain Lockwood leap away while she has the evasive aura before defeating her in the Siege of Boralus on Mythic difficulty." },
            { achID = 12726, titleRU = "Как рыба без воды", titleEN = "A Fish Out of Water", descRU = "Закиньте пятнадцать задыхающихся окуней в воду, а затем победите Вик'Гота во время осады Боралуса в эпохальном режиме.", descEN = "Kick fifteen Gasping Flounders back into the water then defeat Viq'Goth in the Siege of Boralus on Mythic difficulty." },
            { achID = 12722, titleRU = "Собственность мавзолея!", titleEN = "It Belongs in a Mausoleum!", descRU = "Найдите четыре древних украшения в Гробнице королей в эпохальном режиме.", descEN = "Find four ancient trinkets in Kings' Rest on Mythic difficulty." },
            { achID = 12723, titleRU = "Как сохранить мумию", titleEN = "How to Keep a Mummy", descRU = "Освободите мумию Мимию в Гробнице королей в эпохальном режиме.", descEN = "Free Miimii the Mummy in Kings' Rest on Mythic difficulty." },
            { achID = 12721, titleRU = "Бог обертывания", titleEN = "Wrap God", descRU = "Победите Мчимбу Бальзамировщика, не дав ему завершить использование заклинания \"Открыть саркофаг\" так, чтобы при этом погребенные игроки использовали \"Стук изнутри\" не более одного раза за \"Погребение\", в эпохальном режиме.", descEN = "Defeat Mchimba the Embalmer without him finishing a cast of Open Coffin and with entombed players using Struggle no more than once per cast of Entomb on Mythic Difficulty." },
        },
    },
