            { achID = 14291, titleRU = "Кто-то ведь мог споткнуться!", titleEN = "Someone Could Trip on These!", descRU = "Найдите 6 игрушек Призывательницы Туманов в туманах Тирна Скитта в эпохальном режиме.", descEN = "Find Mistcaller's 6 toys in the Mists of Tirna Scithe on Mythic difficulty." },
            { achID = 14375, titleRU = "Жажда знаний", titleEN = "Hunger for Knowledge", descRU = "Победите Тред'ову в туманах Тирна Скитта в эпохальном режиме, после того как уничтожите разумного иглобрюха-поглотителя.", descEN = "Defeat Tred'ova after defeating an Enlightened Spinemaw Gorger in the Mists of Tirna Scithe on Mythic difficulty." },
            { achID = 14347, titleRU = "Осклизлая пища", titleEN = "Full Gores Meal", descRU = "Победите Склизгла в Чумных каскадах в эпохальном режиме, скормив ему три осклизлых лакомства.", descEN = "Defeat Globgrog after feeding him a three course meal in Plaguefall on Mythic difficulty." },
            { achID = 14296, titleRU = "Больше заразы", titleEN = "Going Viral", descRU = "Победите доктора Икуса в Чумных каскадах в эпохальном режиме, уничтожив две нестабильные чумные бомбы.", descEN = "Defeat Doctor Ickus after destroying 2 Volatile Plague Bombs in Plaguefall on Mythic difficulty." },
            { achID = 14292, titleRU = "Осклизлая вечеринка", titleEN = "Riding with my Slimes", descRU = "Победите всех боссов в Чумных каскадах в эпохальном режиме за один поход, пока на вас действует \"Чумной труп\".", descEN = "Defeat all bosses while affected by Plaguefallen within a single visit in Plaguefall on Mythic difficulty." },
            { achID = 14567, titleRU = "Время собирать камни", titleEN = "Picking Up the Pieces", descRU = "Победите Халкиаса в Чертогах Покаяния в эпохальном режиме после того, как он вернет себе три своих фрагмента.", descEN = "Defeat Halkias after he reabsorbs all three Shards of Halkias in the Halls of Atonement on Mythic difficulty." },
            { achID = 14284, titleRU = "Мышка пробежала, хвостиком махнула", titleEN = "Breaking Bad", descRU = "Победите Эшелона, разбив 18 или более неумирающих камнебесов за один раз в Чертогах Покаяния в эпохальном режиме.", descEN = "Defeat Echelon after shattering 18 or more Undying Stonefiends at one time in the Halls of Atonement on Mythic difficulty." },
            { achID = 14352, titleRU = "Не загоняйте Денатрия в угол", titleEN = "Nobody Puts Denathrius in a Corner", descRU = "Победите Лорд-камергера в Чертогах Покаяния в эпохальном режиме, когда в углах зала находится 3 грехокаменные статуи.", descEN = "Defeat Lord Chamberlain with 3 Sinstone Statues in corners of the room in the Halls of Atonement on Mythic difficulty." },
            { achID = 14374, titleRU = "Семейная терапия", titleEN = "Couple's Therapy", descRU = "Победите Манаштормов на Той Стороне в эпохальном режиме, заставив Миллхауса и Миллифисент поразить друг друга \"Неистовством Тьмы\" и \"Сверхмощным лазером \"Два пальца\".", descEN = "Cause Millhouse and Millificent to strike each other with each Shadowfury and Echo Finger Laser X-treme cast and defeat the Manastorms in De Other Side on Mythic difficulty." },
            { achID = 14354, titleRU = "Острая инфекция", titleEN = "Highly Communicable", descRU = "Победите Хаккара, Манаштормов, дилера Зи'ексу и Мве'залу на Той Стороне в эпохальном режиме за один поход, пока хотя бы один участник группы поражен \"Порченой кровью\".", descEN = "Defeat Hakkar, the Manastorms, Dealer Xy'exa, and Mueh'zala while at least one party member is afflicted with Corrupted Blood within a single visit to in De Other Side on Mythic difficulty." },
            { achID = 14606, titleRU = "Надо подумать...", titleEN = "Thinking with...", descRU = "Победите дилера Зи'ексу на Той Стороне в эпохальном режиме, собрав все 5 летающих над ней сфер.", descEN = "Defeat Dealer Xy'exa after collecting all 5 orbs floating above her in De Other Side on Mythic Difficulty." },
            { achID = 14331, titleRU = "Голиаф больше не на связи", titleEN = "Goliath Offline", descRU = "Победите \"Орифрион\" в Шпилях Перерождения в эпохальном режиме, активировав и уничтожив всех трех сломанных опустошителей.", descEN = "Defeat Oryphrion after activating and destroying all three Shattered Devastators in the Spires of Ascension on Mythic difficulty." },
            { achID = 14323, titleRU = "Накопление копий", titleEN = "ExSPEARiential", descRU = "Победите Девию, идеала Сомнения, поразив ее пятью копьями долга в Шпилях Перерождения в эпохальном режиме.", descEN = "Defeat Devos, Paragon of Doubt after hitting her with five Spears of Duty in the Spires of Ascension on Mythic difficulty." },
            { achID = 14327, titleRU = "Отсюда виден мой дом", titleEN = "I Can See My House From Here", descRU = "Соберите все пять сфер в Шпилях Перерождения с интервалом не более 60 секунд после победы над Девией, идеалом Сомнения, в эпохальном режиме.", descEN = "Gather all five orbs within 60 seconds of each other in Spires of Ascension after defeating Devos, Paragon of Doubt in the Spires of Ascension on Mythic difficulty." },
            { achID = 14297, titleRU = "Выбираю всех трех", titleEN = "Three Choose One", descRU = "Победите каждого из противников в \"Оскорблении претендентов\" последним, несколько раз пройдя этот бой в Театре Боли в эпохальном режиме.", descEN = "Defeat each of the combatants last throughout multiple completions of the Affront of Challengers encounter in the Theater of Pain on Mythic difficulty." },
            { achID = 14607, titleRU = "Свежее мясо!", titleEN = "Fresh Meat!", descRU = "Победите Кроворуба в Театре Боли в эпохальном режиме, отбив 2 куска мяса с помощью \"Превращения в отбивную\".", descEN = "Defeat Gorechop after tenderizing 2 hunks of meat with Tenderizing Smash in the Theater of Pain on Mythic difficulty." },
            { achID = 14533, titleRU = "Королевская битва", titleEN = "Royal Rumble", descRU = "Победите Мордрету, Вечную императрицу, в Театре Боли в эпохальном режиме после того, как бросите /вызов и победите 2 призрачных претендентов.", descEN = "Defeat Mordretha, the Endless Empress, after performing a /challenge and defeating 2 Ghostly Contenders in the Theater of Pain on Mythic difficulty." },
            { achID = 14286, titleRU = "Осадочек остался", titleEN = "Residue Evil", descRU = "Победите вершителя Тарвольда, убив 8 подопытных с помощью эффектов \"Осадка\" в Кровавых катакомбах в эпохальном режиме.", descEN = "Defeat Executor Tarvold after slaying 8 Forlorn Captives with the effects of Residue in Sanguine Depths on Mythic difficulty." },
            { achID = 14290, titleRU = "Я за тобой слежу", titleEN = "I Only Have Eyes For You", descRU = "Победите Дараку Несокрушимого в Кровавых катакомбах в эпохальном режиме.", descEN = "Defeat Duraka the Unbreakable in the Sanguine Depths on Mythic difficulty." },
            { achID = 14289, titleRU = "Каменная гостья", titleEN = "Kaal-ed Shot", descRU = "Победите генерала Кааль в Кровавых катакомбах в эпохальном режиме, находясь под действием эффекта \"Получай!\"", descEN = "Defeat General Kaal while affected by Slammed! in the Sanguine Depths on Mythic difficulty." },
        },
    },
