        soloNoteEN = "9 of 10 achievements are soloable, but Lady Inerva Darkvein's braziers require 4 players.",
        subAchievements = {
            { achID = 14293, titleRU = "Слепая злоба", titleEN = "Blind as a Bat", descRU = "Победите Визгунью в замке Нафрия в обычном или более сложном режиме после того, как она убьет шестерых скрытных служителей.", descEN = "Defeat Shriekwing after she kills six Sneaky Servitors in Castle Nathria on Normal difficulty or higher." },
            { achID = 14523, titleRU = "Сделал дело – гуляй смело", titleEN = "Taking Care of Business", descRU = "Победите ловчего Альтимора в замке Нафрия в обычном или более сложном режиме, после того как разведете Маргора, Баргаста и Гекутиса по разным углам псарни.", descEN = "Defeat Huntsman Altimor after walking Margore, Bargast, and Hecutis to the corners of The Kennels in Castle Nathria on Normal difficulty or higher." },
            { achID = 14608, titleRU = "Яркое пламя", titleEN = "Burning Bright", descRU = "Помогите Кель'тасу обрести искупление в замке Нафрия в обычном или более сложном режиме после того, как зажжете все четыре жаровни в зале.", descEN = "Redeem Kael'thas after lighting all four of the room's braziers in Castle Nathria on Normal difficulty or higher." },
            { achID = 14617, titleRU = "Частная коллекция", titleEN = "Private Stock", descRU = "Победите изобретателя Зи'мокса в замке Нафрия в обычном или более сложном режиме, вернув аниму Малдраксуса, Арденвельда и Утробы на витрины.", descEN = "Defeat Artificer Xy'mox after returning loose Maldraxxus, Ardenweald, and Maw Anima to their display cases in Castle Nathria on Normal difficulty or higher." },
            { achID = 14376, titleRU = "Голодный зверь", titleEN = "Feed the Beast", descRU = "Победите алчущего разрушителя после того, как опустошите все большие канистры анимы с помощью \"Нестабильного выброса\" в замке Нафрия в обычном или более сложном режиме.", descEN = "Defeat the Hungering Destroyer after draining all of the large anima canisters with Volatile Ejection in Castle Nathria on Normal difficulty or higher." },
            { achID = 14524, titleRU = "Не знаю, чего мы ожидали", titleEN = "I Don't Know What I Expected", descRU = "Победите леди Инерву Дарквейн в замке Нафрия в обычном или более сложном режиме после того, как уничтожите темного анимуса.", descEN = "Defeat Lady Inerva Darkvein after defeating the Dark Animus in Castle Nathria on Normal difficulty or higher." },
            { achID = 14619, titleRU = "(Не)винно пролитая кровь", titleEN = "Pour Decision Making", descRU = "Победите Совет Крови в замке Нафрия в обычном или более сложном режиме, бросив четыре бутылки с винами разных сортов.", descEN = "Defeat the Council of Blood after throwing four bottles of wine in Castle Nathria on Normal difficulty or higher." },
            { achID = 14294, titleRU = "Месть Глиноптаха", titleEN = "Dirtflap's Revenge", descRU = "Победите Грязешмяка в замке Нафрия в обычном или более сложном режиме после того, как он врежется в колонны в том порядке, который укажет Глиноптах.", descEN = "Defeat Sludgefist after he collides with pillars in Dirtflap's preferred order in Castle Nathria on Normal difficulty or higher." },
            { achID = 14525, titleRU = "Покорми меня, Сеймур!", titleEN = "Feed Me, Seymour!", descRU = "Победите генералов Каменного легиона в замке Нафрия в обычном или более сложном режиме, пока все игроки держат в руках букеты цветущих кровавых роз.", descEN = "Defeat the Stone Legion Generals while all players are carrying a Bouquet of Blooming Sanguine Roses in Castle Nathria on Normal difficulty or higher." },
            { achID = 14610, titleRU = "Чистая совесть", titleEN = "Clear Conscience", descRU = "Победите сира Денатрия в замке Нафрия в обычном или более сложном режиме после того, как снимете \"Бремя греха\" со всех игроков до активации \"Марша кающихся\".", descEN = "Defeat Sire Denathrius after removing Burden of Sin from all players before March of the Penitent is cast in Castle Nathria on Normal difficulty or higher." },
        },
    },
