        soloNoteEN = "8 of 10 achievements are soloable; 2 mechanics require a small group (3+ players).",
        subAchievements = {
            { achID = 14998, titleRU = "Это самая лучшая парочка", titleEN = "Name A Better Duo, I'll Wait", descRU = "Победите Таррагра в Святилище Господства в обычном или более сложном режиме, после того как вы войдете в туман и воссоедините Мориазу с Кнопкой.", descEN = "Defeat The Tarragrue after entering the mists and reuniting Moriaz with Buttons in the Sanctum of Domination on Normal difficulty or higher." },
            { achID = 15065, titleRU = "Эти глаза напротив", titleEN = "Eye Wish You Were Here", descRU = "Победите Око Тюремщика в обычном или более сложном режиме, воспользовавшись трофейной камерой СЕЛФИ и сделав фотографию всего рейда и Ока Тюремщика, после того как оно применит \"Быструю смерть\".", descEN = "Defeat the Eye of the Jailer after using the Scavenged S.E.L.F.I.E. Camera to take a picture of the Eye of the Jailer and the entire raid after it has cast Immediate Extermination in the Sanctum of Domination on Normal difficulty or higher." },
            { achID = 15003, titleRU = "Девять судеб", titleEN = "To the Nines", descRU = "Победите Девятерых в Святилище Господства в обычном или более сложном режиме, образовав осколок судьбы из 9 или более фрагментов судьбы.", descEN = "Defeat The Nine after forming a Shard of Destiny from 9 or more Fragments of Destiny in the Sanctum of Domination on Normal difficulty or higher." },
            { achID = 15105, titleRU = "Танго терзателя", titleEN = "Tormentor's Tango", descRU = "Победите раздирателя душ Дормацайна в Святилище Господства в обычном или более сложном режиме, /поддев Гарроша Адского Крика перед боем и избежав всех попаданий \"Мучения\".", descEN = "Defeat Soulrender Dormazain after /taunting Garrosh Hellscream before combat begins and avoiding all Torment impacts in the Sanctum of Domination on Normal difficulty or higher." },
            { achID = 15058, titleRU = "Дома мы тренировались на подземных крысах", titleEN = "I Used to Bullseye Deeprun Rats Back Home", descRU = "Бросьте сферу точно в цель три раза и победите душу Нер'зула в Святилище Господства в обычном или более сложном режиме.", descEN = "Defeat the Remnant of Ner'zhul after scoring three goals in the Sanctum of Domination on Normal difficulty or higher." },
            { achID = 15131, titleRU = "Душебойка", titleEN = "Whack-A-Soul", descRU = "Победите кузнеца боли Разнала в Святилище Господства в обычном или более сложном режиме, активировав горящие подвесные клетки.", descEN = "Defeat Painsmith Raznal after activating the Burning Gibbets in the Sanctum of Domination on Normal difficulty or higher." },
            { achID = 15132, titleRU = "Знание – сила", titleEN = "Knowledge is Power", descRU = "Победите стражницу Предвечных в Святилище Господства в обычном или более сложном режиме, победив Ваззарена Искателя после просветления.", descEN = "Defeat the Guardian of the First Ones after enlightening and defeating Vazzaren the Seeker in the Sanctum of Domination in Normal difficulty or higher." },
            { achID = 15040, titleRU = "Безупречная судьба", titleEN = "Flawless Fate", descRU = "Победите писаря судьбы Ро-Кало в Святилище Господства в обычном или более сложном режиме, не получив урона от \"Фрагментов судьбы\", \"Судьбоносной связи\" и взрывов \"Зова вечности\" и \"Эха Вечности\".", descEN = "Defeat Fatescribe Roh-Kalo without taking damage from Fate Fragments, Fated Conjunction, or the explosions from Call of Eternity and Echo of Eternity on Normal difficulty or higher." },
            { achID = 15108, titleRU = "Вместе навсегда", titleEN = "Together Forever", descRU = "Победите Кел'Тузада в Святилище Господства в обычном или более сложном режиме, после того как разморозите сердце части его души.", descEN = "Defeat Kel'Thuzad after thawing the Remnant's heart in the Sanctum of Domination on Normal difficulty or higher." },
            { achID = 15133, titleRU = "Мир как призма", titleEN = "This World is a Prism", descRU = "Победите Сильвану Ветрокрылую в Святилище Господства в обычном или более сложном режиме, активировав фокусирующую призму.", descEN = "Defeat Sylvanas Windrunner after activating the Focusing Prism in the Sanctum of Domination on Normal difficulty or higher." },
        },
