        soloable = false,
        minPlayers = 3,
        soloNoteRU = "Большинство боссов закрывается в соло на 80–90 ур., но 2 достижения требуют координированной мини-группы.",
        soloNoteEN = "Most bosses are soloable at level 80–90, with 2 achievements requiring a small group.",
        subAchievements = {
            { achID = 15315, titleRU = "Среди нас", titleEN = "Amidst Ourselves", descRU = "Победите Властителей Ужаса в обычном или более сложном режиме, предварительно выполнив простую задачу во время действия эффекта \"Лазутчики ужаса\" в Гробнице Предвечных.", descEN = "Defeat the Lords of Dread after finding and completing one simple task during Infiltration of Dread in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15397, titleRU = "Цирк четырех колец", titleEN = "Four Ring Circus", descRU = "Победите падшего оракула Даусинь в Гробнице Предвечных в обычном или более сложном режиме, когда кто-то из игроков держит потусторонний сердечник.", descEN = "Defeat Dausegne, the Fallen Oracle, while a player is carrying the Afterlife Core in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15381, titleRU = "Энергия подключена", titleEN = "Power ON", descRU = "Победите Бдительного Стража в обычном или более сложном режиме в Гробнице Предвечных после победы над истощенным автомом.", descEN = "Defeat the Vigilant Guardian after defeating the Depleted Automa in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15386, titleRU = "Мерцающие тайны", titleEN = "Shimmering Secrets", descRU = "Победите Галондрия Возвращающего в обычном или более сложном режиме в Гробнице Предвечных, собрав шесть странных артефактов и уничтожив механизмы.", descEN = "Defeat Halondrus the Reclaimer after collecting six strange artifacts and defeating their constructs in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15419, titleRU = "Матрица протоформы", titleEN = "The Protoform Matrix", descRU = "Победите Лихувима в Гробнице Предвечных в обычном или более сложном режиме, синтезировав и победив автома-разорителя Нео.", descEN = "Defeat Lihuvim after synthesizing and defeating a Reaving Automa: Neo in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15396, titleRU = "Все мы дети звезд", titleEN = "We Are All Made of Stars", descRU = "Победите Ригелона в обычном или более сложном режиме в Гробнице Предвечных, когда на всех игроков действует эффект \"Глашатай космоса\".", descEN = "Defeat Rygelon with all players under the effects of Herald of the Cosmos in the Sepulcher of the First Ones on Normal Difficulty or higher." },
            { achID = 15400, titleRU = "Дикие, но симпатичные корги", titleEN = "Where the Wild Corgis Are", descRU = "Победите прототип Пантеона в Гробнице Предвечных в обычном или более сложном режиме, после того как каждый игрок погладит 5 корги во время действия \"Звериного натиска\".", descEN = "Defeat the Prototype Pantheon after each player has petted 5 Corgis during Wild Stampede in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15401, titleRU = "Мудрость приходит из пустыни", titleEN = "Wisdom Comes From the Desert", descRU = "Победите ненасытного разорителя Сколекса в Гробнице Предвечных в обычном или более сложном режиме после того, как он закопается под всеми четырьмя пилонами памяти и уничтожит их.", descEN = "Defeat Skolex, the Insatiable Ravener after getting it to burrow under and destroy all four Memorial Pylons in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15398, titleRU = "Зи'мокс смог, и ты смоги!", titleEN = "Xy Never, Ever Marks the Spot.", descRU = "Победите Зи'мокса в Гробнице Предвечных в обычном или более сложном режиме, когда на всех игроков действуют эффекты краденых артефактов.", descEN = "Defeat Xy'mox with all players under the effects of pilfered artifacts in the Sepulcher of the First Ones on Normal difficulty or higher." },
            { achID = 15494, titleRU = "Проклятая авиация", titleEN = "Damnation Aviation", descRU = "Победите Тюремщика, подобрав шесть сфер Прародителей в Гробнице Предвечных в обычном или более сложном режиме.", descEN = "Defeat the Jailer after collecting 6 Progenitor Orbs in the Sepulcher of the First Ones on Normal difficulty or higher." },
        },
    },
