        titleRU = "Слава герою Dragonflight",
        titleEN = "Glory of the Dragonflight Hero",
        expansionRU = "Dragonflight",
        expansionEN = "Dragonflight",
        instanceRU = "Эпохальные подземелья Dragonflight",
        instanceEN = "Dragonflight Mythic Dungeons",
        zoneRU = "Вальдраккен (Драконьи острова)",
        zoneEN = "Valdrakken (Dragon Isles)",
        mapID = 2112, x = 50.0, y = 50.0,
        soloable = false,
        minPlayers = 2,
        soloNoteRU = "Почти все 24 достижения закрываются в соло на 90 ур., кроме 2 групповых механик.",
        soloNoteEN = "Nearly all 24 achievements are soloable at level 90, except 2 group mechanics.",
        subAchievements = {
            { achID = 16434, titleRU = "Встретимся после уроков", titleEN = "See Me After Class", descRU = "Победите Вексама в академии Алгет'ар в эпохальном режиме так, чтобы игроки не поглотили ни одной чародейской сферы.", descEN = "Defeat Vexamus without players absorbing any Arcane Orbs in Algeth'ar Academy on Mythic Difficulty." },
            { achID = 16329, titleRU = "Кря-кря не зря!", titleEN = "Duck, Duck, Spruce!", descRU = "Победите заросшее древо в академии Алгет'ар в эпохальном режиме, пока у всех участников группы на голове сидит сытый утенок.", descEN = "Defeat the Overgrown Ancient while all party members have a Well-Fed Duckling on their head in Algeth'ar Academy on Mythic difficulty." },
            { achID = 16296, titleRU = "Собачья работа", titleEN = "Growlbossify", descRU = "Освободите вождя Мягкую Лапу, вооружите ее копьем и щитом, доведите ее живой до конца подземелья, а затем победите боевой отряд Когтерезки в лощине Бурошкуров в эпохальном режиме.", descEN = "Defeat Hackclaw's War-Band after freeing Chief Softpaw, equipping her with a spear and shield, and making sure she survives in Brackenhide Hollow on Mythic difficulty." },
            { achID = 16430, titleRU = "Плотоядное растение", titleEN = "All Bark, All Bite", descRU = "Победите Древорта в лощине Бурошкуров в эпохальном режиме после того, как он поглотит каждого игрока.", descEN = "Defeat Treemouth after every player has been consumed at least once in Brackenhide Hollow on Mythic difficulty." },
            { achID = 16404, titleRU = "Я тебя посадил, я тебя и убью", titleEN = "So You Can Kill This in a Way That Matters...", descRU = "Найдите и посадите три живучих гриба, уничтожьте их \"Ударом разложения\", а затем победите гниломага Око Гнева в лощине Бурошкуров в эпохальном режиме.", descEN = "Defeat Decatriarch Wratheye after finding and planting three Resilient Mushrooms, then destroying them with Decaystrike in Brackenhide Hollow on Mythic difficulty." },
            { achID = 16517, titleRU = "Токсичная команда", titleEN = "Toxicity Strike Team", descRU = "Победите токсичную рогоплавиху, прочистив водоприемники в Чертогах Насыщения в эпохальном режиме.", descEN = "Defeat the Toxic Swogmother after Purging the Water Intakes in Halls of Infusion on Mythic difficulty." },
            { achID = 16426, titleRU = "Страшно голодный рогоплав", titleEN = "Hungry Hungry Hornswog", descRU = "Победите голиафа-проглота в Чертогах Насыщения в эпохальном режиме после того, как он станет золоден и проглотит 10 любопытных детенышей рогоплава.", descEN = "Defeat the Gulping Goliath after forcing it to become Hangry and devour 10 Curious Swoglets in Halls of Infusion on Mythic difficulty." },
            { achID = 16427, titleRU = "Плыви по течению", titleEN = "Go With the Flow", descRU = "Уничтожьте три регулятора потока, а затем победите изначальное цунами в Чертогах Насыщения в эпохальном режиме.", descEN = "Defeat the Primal Tsunami after slaying three Flow Control Units in Halls of Infusion on Mythic difficulty." },
            { achID = 16438, titleRU = "Знания... сохранены?", titleEN = "Knowledge is... Preserved?", descRU = "Сожгите не более 15 книг, а затем победите Чаргата Дробителя Чешуи в Нелтарии в эпохальном режиме.", descEN = "Defeat Chargath, Bane of Scales while burning less than 15 books in Neltharus on Mythic difficulty." },
            { achID = 16432, titleRU = "К рейду готов VIII", titleEN = "Ready for Raiding VIII", descRU = "Победите главного кузнеца Горека в Нелтарии в эпохальном режиме, избежав \"Огня кузни\", \"Кузнечного огня\", \"Извержения пламени\", \"Пылающей эгиды\" другого игрока и последнего \"Разгоряченного удара\".", descEN = "Defeat Forgemaster Gorek without being struck by Forgestorm, Forgefire, Blazing Eruptions, another player's Blazing Aegis, or the final slam of Heated Swings in Neltharus on Mythic difficulty." },
            { achID = 16453, titleRU = "Жидкая магма", titleEN = "Liquid Hot Magma", descRU = "Победите Магмобивня в Нелтарии в эпохальном режиме после того, как он мутирует от драконьего настоя.", descEN = "Defeat Magmatusk after it has been mutated with Draconic Tincture in Neltharus on Mythic difficulty." },
            { achID = 16440, titleRU = "Приемная мать стаи", titleEN = "Are You My Broodmother?", descRU = "Охладите, обожгите, накалите и сохраните живым молодое рубиновое яйцо, а затем победите Киракку и Эркхарта Кровь Бури в Рубиновых Омутах Жизни в эпохальном режиме.", descEN = "Defeat Kyrakka and Erkhart Stormvein after chilling, searing, tempering, and keeping alive the Nascent Ruby Egg in Ruby Life Pools on Mythic difficulty." },
            { achID = 16402, titleRU = "Очки убийства драконов", titleEN = "Dragon Kill Points", descRU = "Убейте 40 заряженных дракончиков, а затем победите Мелидруссу в Рубиновых Омутах Жизни в эпохальном режиме.", descEN = "Defeat Melidrussa after defeating 40 of her chamber's Infused Whelps in Ruby Life Pools on Mythic difficulty." },
            { achID = 16320, titleRU = "Наносит ли пар урон от огня?", titleEN = "Does Steam Do Fire Damage?", descRU = "Победите Кокию Пламенное Копыто в Рубиновых Омутах Жизни в эпохальном режиме после того, как разогреете 4 омута с помощью пылающего валуна.", descEN = "Defeat Kokia Blazehoof after heating up 4 life pools with Molten Boulder in Ruby Life Pools on Mythic difficulty." },
            { achID = 16330, titleRU = "Рожденные прятаться", titleEN = "You Must Be Made of Hide", descRU = "Победите Мраскула в Лазурном хранилище в эпохальном режиме, не активируя превращающую ловушку или способность \"Визг\".", descEN = "Defeat Umbrelskul without being hit by a polymorph trap or triggering a Shriek in The Azure Vault on Mythic difficulty." },
            { achID = 16445, titleRU = "Холоднее некуда", titleEN = "Icy What You Did There", descRU = "Примените \"Морозный опустошитель\" к леденящему кристаллу 12 раз и создайте изрядно леденящий кристалл, а затем победите Телаша Серокрылого в Лазурном хранилище в эпохальном режиме.", descEN = "Defeat Telash Greywing after using Icy Devastator 12 times on an Icy Crystal to create a Very Icy Crystal in The Azure Vault on Mythic difficulty." },
            { achID = 16331, titleRU = "Треснувший кристалл", titleEN = "The Cracked Crystal", descRU = "Разбейте мерцающие жеоды \"Ударом дракона\" и уничтожьте 9 крупных жеод, а затем победите Мраскула в Лазурном хранилище в эпохальном режиме.", descEN = "Defeat Umbrelskul after smashing Shimmering Geodes with Dragon Strike and destroying 9 Geode Chunks in The Azure Vault on Mythic difficulty." },
            { achID = 16447, titleRU = "Ну какова вероятность...", titleEN = "What Are The Chances...", descRU = "Поразите одного игрока пятью ударами молнии одновременно и убейте элементаля бури, а затем победите яростную бурю в наступлении клана Нокхуд в эпохальном режиме.", descEN = "Defeat the Raging Tempest after striking a single player with 5 Lightning Strikes simultaneously and defeating a Storm Elemental in The Nokhud Offensive on Mythic difficulty." },
            { achID = 16456, titleRU = "Оружие Марукая", titleEN = "Weapons of the Maruukai", descRU = "Победите Тииру и Маруука с копьем Толуи, топором Берке и луком Сартака в наступлении клана Нокхуд в эпохальном режиме.", descEN = "Defeat Teera and Maruuk while holding the Spear of Tolui, War Axe of Berke, and Bow of Sartaq in The Nokhud Offensive on Mythic difficulty." },
            { achID = 16620, titleRU = "Инкубация яиц охуна", titleEN = "Ohuna Incubation", descRU = "Принесите восемь теплых яиц охуна заводчику охунов Таруку за одно прохождение наступления клана Нокхуд в эпохальном режиме.", descEN = "Deliver eight warm ohuna eggs to Ohuna Keeper Taruk in a single visit to The Nokhud Offensive on Mythic difficulty." },
            { achID = 16602, titleRU = "Хан Болван", titleEN = "Nokhud Deed Goes Unnoticed", descRU = "Полностью исцелите Он'ару, а затем победите хана Балакара в наступлении клана Нокхуд в эпохальном режиме.", descEN = "Defeat Balakar Khan after healing Ohn'ahra to full health in The Nokhud Offensive on Mythic difficulty." },
            { achID = 16337, titleRU = "Трогг трогга не трогай", titleEN = "It's a Trogg Eat Trogg World", descRU = "Победите Бромача, пока 10 или более троггов из племени Каменного Свода еще живо, в подземелье \"Ульдаман: наследие Тира\" в эпохальном режиме.", descEN = "Defeat Bromach while 10 or more Stonevault Troggs are still alive in Uldaman: Legacy of Tyr on Mythic difficulty." },
            { achID = 16282, titleRU = "Взаимное ошеломление", titleEN = "No, You're Stunning!", descRU = "Победите часовую Талондрас, одновременно оглушив ее и всех участников группы в подземелье \"Ульдаман: наследие Тира\" в эпохальном режиме.", descEN = "Defeat Sentinel Talondras after simultaneously stunning both Sentinel Talondras and all party members in Uldaman: Legacy of Tyr on Mythic difficulty." },
            { achID = 16281, titleRU = "Как песок в часах", titleEN = "Like Sands Through the Hourglass", descRU = "Победите хронолорда Дейоса, поймав 20 падающих вечных сфер в подземелье \"Ульдаман: наследие Тира\" в эпохальном режиме.", descEN = "Defeat Chrono-Lord Deios after catching 20 Eternity Orbs as they fall to the ground in Uldaman: Legacy of Tyr on Mythic difficulty." },
        },
    },
