        mapID = 2025, x = 74.6, y = 55.4,
        soloable = false,
        minPlayers = 3,
        soloNoteRU = "Часть достижений закрывается в соло на 90 ур., для остальных удобнее собрать мини-группу 3–5 человек в Поиске групп.",
        soloNoteEN = "Several criteria are soloable at level 90; a 3–5 player group is recommended for the remaining mechanics.",
        subAchievements = {
            { achID = 16335, titleRU = "Зачем эта ледяная штука", titleEN = "What Frozen Things Do", descRU = "Победите Эранога в Хранилище Воплощений в обычном или более сложном режиме после того, как отыщете ледяной камень портала и победите пылающее чудище.", descEN = "Defeat Eranog after finding a Frozen Portal Stone and defeating a Burning Behemoth in Vault of the Incarnates on Normal difficulty or higher." },
            { achID = 16365, titleRU = "Братья меньшие", titleEN = "Little Friends", descRU = "Поразите три ядра дремлющей земли \"Пробужденной землей\", убейте появившихся существ накаленной земли, а затем победите Терроса в Хранилище Воплощений в обычном или более сложном режиме.", descEN = "Defeat Terros after hitting the three Dormant Earth nodes in his chamber with Awakened Earth and then defeating the resultant Energized Earth creatures in Vault of the Incarnates on Normal difficulty or higher." },
            { achID = 16364, titleRU = "В глубинах лавы", titleEN = "The Lunker Below", descRU = "Выманите из лавы глубинного гиганта рыболовной приманкой, а затем победите Совет стихий в Хранилище Воплощений в обычном или более сложном режиме.", descEN = "Use fishing to lure the Lurking Lunker living in the lava out, then engage and defeat the Primal Council in the Vault of the Incarnates on Normal difficulty or higher." },
            { achID = 16419, titleRU = "Оставлю на потом", titleEN = "I Was Saving That For Later", descRU = "Найдите и освободите 5 таинственных пленников с помощью \"Едкого взрыва\", понаблюдайте за их гибелью, а затем победите Сеннарт Дыхание Льда в Хранилище Воплощений в обычном или более высоком режиме.", descEN = "Defeat Sennarth, The Cold Breath after finding and freeing 5 mysterious captives using Caustic Eruption, then witnessing their demise in Vault of the Incarnates on Normal difficulty or higher." },
            { achID = 16458, titleRU = "Ничего кроме воздуха", titleEN = "Nothing But Air", descRU = "Победите Дафию Перерожденную, собрав 8 сгустившихся бурь в Хранилище Воплощений в обычном или более сложном режиме.", descEN = "Defeat Dathea, Ascended after collecting 8 Condensed Gales in Vault of the Incarnates on Normal difficulty or higher." },
            { achID = 16450, titleRU = "Это МОЯ сила!", titleEN = "The Power is MINE!", descRU = "Уничтожьте изначальную аватару и победите Курога Зловещий Тотем в Хранилище Воплощений в обычном или более сложном режиме.", descEN = "Defeat Kurog Grimtotem after destroying the Primal Avatar in Vault of the Incarnates on Normal difficulty or higher." },
            { achID = 16442, titleRU = "Скоростная инкубация", titleEN = "Incubation Extermination", descRU = "Выведите командиров из всех яиц изначальных стихий и убейте их с интервалом не более чем в 10 секунд, а зачем победите хранительницу стаи Денну в Хранилище Воплощений в обычном или более высоком режиме.", descEN = "Defeat Broodkeeper Diurna after successfully hatching and defeating lieutenants from each Primal element's eggs within 10 seconds of each other in Vault of the Incarnates on Normal difficulty or higher." },
            { achID = 16451, titleRU = "Унесенная бурей", titleEN = "The Ol Raszle Daszle", descRU = "Победите Рашагет Пожирательницу Бурь в Хранилище Воплощений в обычном или более сложном режиме, собрав две сущности сосредоточенной бури и уничтожив сосредоточенную бурю.", descEN = "Defeat Raszageth the Storm-Eater after successfully gathering two Concentrated Storm Essences and defeating the Concentrated Storm in Vault of the Incarnates on Normal difficulty or higher." },
        },
    },
    {
