        expansionRU = "Dragonflight",
        expansionEN = "Dragonflight",
        instanceRU = "Аберрий, Затенённое Горнило",
        instanceEN = "Aberrus, the Shadowed Crucible",
        zoneRU = "Пещера Заралек",
        zoneEN = "Zaralek Cavern",
        mapID = 2133, x = 48.2, y = 12.0,
        soloable = false,
        minPlayers = 3,
        soloNoteRU = "Для части механик («Потерянные и найденные») требуется группа из нескольких игроков.",
        soloNoteEN = "Several mechanics require a small group of players.",
        subAchievements = {
            { achID = 18229, titleRU = "Кошмарный костюм", titleEN = "Cosplate", descRU = "Победите Каззару Огнекованную, разбив свою пластину огнекованной стали в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat Kazzara, the Hellforged after shattering your own Hellsteel Plating in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 18168, titleRU = "Я сделаю свое пламя Тьмы", titleEN = "I'll Make My Own Shadowflame", descRU = "Примените \"Теневую детонацию\", \"Огненный метеор\" и \"Обжигающий сумрак\" к забытому контейнеру с образцом, чтобы создать останки пламени Тьмы, а затем уничтожьте их и победите слияние пламени Тьмы в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat the Shadowflame Amalgamation after using Umbral Detonation, Fiery Meteor and Blistering Twilight on a Forgotten Specimen Tank to create and extinguish a Shadowflame Remnant in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 18173, titleRU = "С чистого листа", titleEN = "Tabula Rasa", descRU = "Победите забытые эксперименты, после того как Нутраала три раза поразит \"Раздирающий рывок\", \"Нестабильный плевок\" и \"Глубокий вдох\" в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat The Forgotten Experiments after Nutraal is hit 3 times by Rending Charge, Volatile Spew, and Deep Breath in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 18228, titleRU = "Вы вообще стараетесь?", titleEN = "Are You Even Trying?", descRU = "Разбейте нападение закали, поразив указанных ниже существ пещерным камнем в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat the Assault of the Zaqali after hitting the following creatures with a Cave Pebble in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 18230, titleRU = "Попади в рогоплава", titleEN = "Whac-A-Swog", descRU = "Победите Рашока Древнего, 5 раз поразив затерянного гиганта \"Обжигающим ударом\" в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat Rashok, the Elder after hitting the Lost Lunker with Searing Slam 5 times in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 18193, titleRU = "Хрупкая победа", titleEN = "Eggscellent Eggsecution", descRU = "Победите бдительного распорядителя Зкарна, пока участник рейда переносит хрупкое экспериментальное яйцо в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat The Vigilant Steward, Zskarn while a member of your raid is carrying the Delicate Experimental Egg in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 18172, titleRU = "Улитки, вперед!", titleEN = "Escar-Go-Go-Go", descRU = "Победите Магморакса, скормив ему 20 жгучих лавовых улиток в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat Magmorax after feeding him 20 Spicy Lava Snails in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 18149, titleRU = "Повреждено при транспортировке", titleEN = "Objects in Transit May Shatter", descRU = "Пробейте стены искаженной земли, держа испорченный эксперимент, стопку свитков, негорящую черную свечу и переносную черную наковальню, а затем победите эхо Нелтариона в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat the Echo of Neltharion after players smash through walls of Twisted Earth while carrying the Expired Experiment, the Stack of Scrolls, the Neverburning Ebon Candle, and the \"Portable\" Ebon Anvil in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
            { achID = 17877, titleRU = "Больше мы это не увидим... правда?", titleEN = "We'll Never See That Again, Surely", descRU = "Победите дракомандира Саркарета, вырастив массу плоти и бросив ее в межзвездную пустоту в обычном или более сложном режиме рейда \"Аберрий, Затененное Горнило\".", descEN = "Defeat Scalecommander Sarkareth after cultivating a Lump of Flesh and hurling it into the Emptiness Between Stars in Aberrus, the Shadowed Crucible on Normal difficulty or higher." },
