            { achID = 19393, titleRU = "Спасательная операция", titleEN = "Whelp, I'm Lost", descRU = "Спасите 6 потерявшихся дракончиков, а затем победите Тиндрала Полет Мысли в обычном или более сложном режиме рейда \"Амирдрассил, Надежда Сна\".", descEN = "Defeat Tindral Sageswift after rescuing 6 Lost Whelps in Amirdrassil, the Dream's Hope on Normal Difficulty or higher." },
